-- =============================================================================
-- 435 — LE CAHIER D'EXERCICES DE 1RE
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 435 --niveau 1re --matieres francais > supabase/contenu/435_exercices_1re.sql
--
-- 93 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.k070           33 exercices · 11 chapitres
--   francais.k071           33 exercices · 11 chapitres
--   francais.k072           27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b199ad65-bc32-53d9-a241-05269915211a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le sommaire de la Déclaration","competence":"analyser-document","situation":"Pour préparer ton oral, tu as recopié le plan de la Déclaration d’Olympe de Gouges, mais les parties sont en désordre. Remets de l’ordre, puis relis la phrase la plus célèbre du texte.","documents":[{"id":"sommaire","type":"fiche","modele":"affiche","entete":"Sommaire en désordre","sousTitre":"Déclaration des droits de la femme et de la citoyenne (1791)","emoji":"📜","teinte":"violet","lignes":[{"texte":"Le postambule","id":"z1"},{"texte":"Le contrat social de l’homme et de la femme","id":"z2"},{"texte":"La dédicace","id":"z3"},{"texte":"Les dix-sept articles","id":"z4"},{"texte":"Le préambule","id":"z5"}],"pied":"Plan à reconstituer"},{"id":"artx","type":"texte","genre":"source","titre":"Article X (extrait)","blocs":["« La femme a le droit de monter sur l’échafaud ; elle doit avoir également celui de monter à la tribune. »"],"source":"Olympe de Gouges, Déclaration des droits de la femme et de la citoyenne, 1791"}],"questions":[{"enonce":"Touche la partie où les « mères, filles, sœurs, représentantes de la nation » demandent à être constituées en Assemblée.","aide":"Cette partie ouvre les articles ; elle est calquée sur celle de 1789.","type":"zone","document":"sommaire","multiple":false},{"enonce":"Remets les parties dans l’ordre où on les lit.","aide":"Le texte commence par une dédicace et finit par le contrat social.","type":"ordre","items":[{"id":"a","texte":"Le contrat social de l’homme et de la femme"},{"id":"b","texte":"La dédicace"},{"id":"c","texte":"Le postambule"},{"id":"d","texte":"Le préambule"},{"id":"e","texte":"Les dix-sept articles"}]},{"enonce":"Dans l’article X, touche les deux mots qui désignent les deux lieux que la femme doit pouvoir atteindre.","aide":"Un lieu de châtiment, un lieu de parole.","type":"zone","document":"artx","multiple":true},{"enonce":"Quel est l’argument de l’article X ?","aide":"Relis les deux moitiés de la phrase : que se passe-t-il dans la première, que réclame la seconde ?","type":"choix","options":[{"id":"a","texte":"Les hommes doivent monter à la tribune à leur place, puisqu’elles risquent l’échafaud"},{"id":"b","texte":"Les femmes doivent éviter la politique pour éviter l’échafaud et la prison"},{"id":"c","texte":"Puisque la loi punit les femmes comme des citoyennes, elle doit les représenter"},{"id":"d","texte":"La tribune est aussi dangereuse que l’échafaud, donc les femmes doivent s’en écarter"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"C’est **le préambule** : il reprend celui de 1789 pour y faire entrer les femmes."},{"cle":{"type":"ordre","ids":["b","d","e","c","a"]},"explication":"Ordre : **dédicace, préambule, dix-sept articles, postambule, contrat social**."},{"cle":{"type":"zone","ids":["m9","m19"]},"explication":"Les deux lieux sont **l’échafaud** et **la tribune** : la loi punit les femmes, elle doit donc aussi les laisser parler."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’argument est **imparable** : si la femme est jugée et punie en citoyenne, elle doit l’être aussi pour parler et pour voter."}]$ex$::jsonb),
  ('b199ad65-bc32-53d9-a241-05269915211a'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"1789 et 1791 face à face","competence":"analyser-texte","situation":"Olympe de Gouges a repris la forme de la Déclaration de 1789. Compare les deux premiers articles, puis mesure ce qui change et ce qui reste.","documents":[{"id":"a1789","type":"texte","genre":"source","titre":"Article premier, 1789","blocs":["« Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l’utilité commune. »"],"source":"Déclaration des droits de l’homme et du citoyen, 1789"},{"id":"a1791","type":"texte","genre":"source","titre":"Article premier, 1791","blocs":["« La femme naît libre et demeure égale à l’homme en droits. Les distinctions sociales ne peuvent être fondées que sur l’utilité commune. »"],"source":"Olympe de Gouges, Déclaration des droits de la femme et de la citoyenne, 1791"}],"questions":[{"enonce":"Dans le texte de 1791, touche le mot qui prend la place de « hommes » comme sujet.","aide":"Compare la première phrase des deux articles.","type":"zone","document":"a1791","multiple":false},{"enonce":"Range chaque élément : Olympe de Gouges le reprend de 1789 ou l’ajoute ?","aide":"Le postambule et le contrat social n’existent pas en 1789.","type":"categories","categories":[{"id":"c0","texte":"Repris de 1789"},{"id":"c1","texte":"Ajouté en 1791"}],"items":[{"id":"i0","texte":"La structure : préambule puis articles"},{"id":"i1","texte":"Le postambule"},{"id":"i2","texte":"La numérotation des articles"},{"id":"i3","texte":"L’ordre des articles"},{"id":"i4","texte":"Le contrat social de l’homme et de la femme"}]},{"enonce":"Pourquoi ce pastiche est-il plus efficace qu’un long plaidoyer ?","aide":"Que fait le lecteur qui reconnaît le modèle ?","type":"choix","options":[{"id":"a","texte":"Il flatte les auteurs de 1789 pour les amener à changer d’avis"},{"id":"b","texte":"Il est plus court à lire et donc moins ennuyeux pour le lecteur"},{"id":"c","texte":"Il évite de citer le texte de 1789 pour ne pas lasser le lecteur"},{"id":"d","texte":"Le lecteur compare lui-même et voit que les femmes ont été oubliées"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"C’est **femme** : le sujet change, tout le reste de la phrase est déjà là."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"Elle **reprend** la forme (articles, numérotation, ordre) et **ajoute** le postambule et le contrat social."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le lecteur **fait lui-même la comparaison** : l’oubli des femmes devient visible sans qu’il soit besoin de le démontrer."}]$ex$::jsonb),
  ('b199ad65-bc32-53d9-a241-05269915211a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une autrice, une date, un prix","competence":"se-reperer-temps","situation":"Tu prépares un entretien sur Olympe de Gouges : croise sa vie, la Révolution et un extrait du postambule pour comprendre son audace.","documents":[{"id":"frise","type":"frise","titre":"La Révolution et la Déclaration","debut":1786,"fin":1794,"pas":1,"evenements":[{"id":"z1","date":1789,"nom":"Droits de l’homme"},{"id":"z2","date":1791,"nom":"Sa Déclaration"},{"id":"z3","date":1793,"nom":"Guillotinée"}]},{"id":"idt","type":"fiche","modele":"affiche","entete":"Marie Gouze, dite Olympe de Gouges","sousTitre":"Carte d’identité","emoji":"🎭","teinte":"violet","lignes":[{"texte":"Née","valeur":"1748, Montauban"},{"texte":"Écrit","valeur":"Du théâtre"},{"texte":"Position","valeur":"Révolutionnaire modérée"}],"pied":"Autrice et militante"},{"id":"post","type":"texte","genre":"source","titre":"Le postambule (extrait)","blocs":["« Femme, réveille-toi ; le tocsin de la raison se fait entendre dans tout l’univers ; reconnais tes droits. »"],"source":"Olympe de Gouges, 1791"}],"questions":[{"enonce":"Sur la frise, touche l’année où paraît la Déclaration d’Olympe de Gouges.","aide":"Elle répond à un texte publié deux ans plus tôt.","type":"zone","document":"frise","multiple":false},{"enonce":"Quel âge a Olympe de Gouges en 1791 ? Utilise sa carte d’identité.","aide":"Soustrais la date de naissance.","type":"nombre"},{"enonce":"Dans le postambule, touche les trois mots qui s’adressent directement aux femmes (l’apostrophe et les ordres).","aide":"Un nom qu’on interpelle, puis deux verbes à l’impératif.","type":"zone","document":"post","multiple":true},{"enonce":"Pourquoi Olympe de Gouges change-t-elle de registre au postambule ?","aide":"À qui ces ordres s’adressent-ils ?","type":"choix","options":[{"id":"a","texte":"Elle veut adoucir le ton pour ne pas froisser la reine"},{"id":"b","texte":"La loi ne suffit pas : il faut aussi convaincre les femmes elles-mêmes"},{"id":"c","texte":"Elle a terminé la liste des articles et change simplement de sujet"},{"id":"d","texte":"Elle veut imiter le style de la Déclaration de 1789 jusqu’au bout"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Elle paraît en **1791**, deux ans après la Déclaration de 1789."},{"cle":{"type":"nombre","valeur":43,"tolerance":1},"affichage":"43","explication":"1791 − 1748 = **43 ans** environ : elle n’est plus une débutante quand elle prend la plume."},{"cle":{"type":"zone","ids":["m0","m1","m14"]},"explication":"Touche **Femme** (apostrophe), **réveille-toi** et **reconnais** (impératifs) : le ton n’est plus juridique mais polémique."},{"cle":{"type":"choix","ids":["b"]},"explication":"La loi ne suffit pas : **il faut convaincre les femmes elles-mêmes**, d’où l’apostrophe et l’impératif."}]$ex$::jsonb),
  ('22812fc6-a156-5bcc-b9bc-9d3e813162dc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois registres, trois publics","competence":"analyser-texte","situation":"Dans son texte, Olympe de Gouges ne parle pas à tout le monde de la même façon. Associe chaque partie à son registre, puis repère l’apostrophe dans un court passage imité.","documents":[{"id":"reg","type":"tableau","titre":"Les trois registres","colonnes":["Partie du texte","Registre","Public visé"],"lignes":[["Les dix-sept articles","?","Les législateurs"],["Le postambule","?","Les femmes"],["Le contrat social","?","Tous"]],"enteteLignes":true},{"id":"imite","type":"texte","genre":"recit","titre":"Un postambule imité","blocs":["Femmes, levez-vous ! Combien de temps encore accepterez-vous qu’on vous flatte pour mieux vous faire taire ? Reconnaissez vos droits !"],"source":"Texte écrit pour l’exercice, à la manière du postambule"}],"questions":[{"enonce":"Associe chaque partie du texte à son registre.","aide":"Le registre s’accorde au public que visent les parties.","type":"association","gauche":[{"id":"g0","texte":"Les dix-sept articles"},{"id":"g1","texte":"Le postambule"},{"id":"g2","texte":"Le contrat social"}],"droite":[{"id":"d0","texte":"Didactique"},{"id":"d1","texte":"Juridique"},{"id":"d2","texte":"Polémique"}]},{"enonce":"Touche les deux verbes à l’impératif dans le passage imité.","aide":"L’impératif donne un ordre : « fais », « faites ».","type":"zone","document":"imite","multiple":true},{"enonce":"Quel effet produit la question du passage imité ?","aide":"Attend-on vraiment une réponse à « Combien de temps encore… » ?","type":"choix","options":[{"id":"a","texte":"Elle interpelle les lectrices et les pousse à réagir"},{"id":"b","texte":"Elle demande un renseignement précis à la lectrice"},{"id":"c","texte":"Elle adoucit le ton pour rassurer les lecteurs"},{"id":"d","texte":"Elle résume les articles de loi en une phrase"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Les articles sont **juridiques** (ils parlent aux législateurs), le postambule **polémique** (il secoue les femmes), le contrat **didactique** (il propose des solutions)."},{"cle":{"type":"zone","ids":["m1","m16"]},"explication":"Les impératifs sont **levez-vous** et **Reconnaissez** : ils appartiennent au registre polémique."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est une question qui **interpelle** : elle relève de la polémique, non de l’information."}]$ex$::jsonb),
  ('22812fc6-a156-5bcc-b9bc-9d3e813162dc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce que le texte réclame, ce qu’il laisse de côté","competence":"argumenter","situation":"Un bon devoir sur Olympe de Gouges mesure l’ampleur de ses demandes, puis pointe les limites de son texte sans le condamner.","documents":[{"id":"revend","type":"fiche","modele":"affiche","entete":"Ce que réclame le texte","sousTitre":"Quatre égalités","emoji":"⚖️","teinte":"violet","lignes":[{"texte":"Voter et être élue","id":"z1"},{"texte":"Hériter et posséder des biens","id":"z2"},{"texte":"Parler en public et publier","id":"z3"},{"texte":"Être reconnue comme sujet de droit","id":"z4"}],"pied":"Programme complet"}],"questions":[{"enonce":"Associe chaque demande à l’égalité qu’elle recouvre.","aide":"Quatre mots : politique, civile, d’expression, de statut.","type":"association","gauche":[{"id":"g0","texte":"Voter et être élue"},{"id":"g1","texte":"Hériter et posséder des biens"},{"id":"g2","texte":"Parler en public et publier"},{"id":"g3","texte":"Être reconnue comme sujet de droit"}],"droite":[{"id":"d0","texte":"Égalité politique"},{"id":"d1","texte":"Égalité d’expression"},{"id":"d2","texte":"Égalité civile"},{"id":"d3","texte":"Égalité de statut"}]},{"enonce":"Touche la demande qui veut que la femme ne soit plus seulement protégée.","aide":"Être protégée, c’est dépendre ; être sujet, c’est décider.","type":"zone","document":"revend","multiple":false},{"enonce":"Range chaque trait du texte : force ou limite ?","aide":"Une limite, c’est ce qui relève des catégories de l’époque.","type":"categories","categories":[{"id":"c0","texte":"Une force du texte"},{"id":"c1","texte":"Une limite du texte"}],"items":[{"id":"i0","texte":"Il reprend la forme de 1789"},{"id":"i1","texte":"Il s’adresse d’abord aux femmes instruites"},{"id":"i2","texte":"Il garde un vocabulaire de la « nature » féminine"},{"id":"i3","texte":"Il parle la langue des législateurs"},{"id":"i4","texte":"Il réclame aussi l’égalité civile"}]},{"enonce":"Pourquoi un bon devoir mentionne-t-il ces limites ?","aide":"Un texte du XVIIIe siècle peut-il penser hors de son temps ?","type":"choix","options":[{"id":"a","texte":"Elles situent le texte dans son époque sans le condamner"},{"id":"b","texte":"Elles prouvent que le texte est sans valeur aujourd’hui"},{"id":"c","texte":"Elles montrent que l’élève n’a pas lu le texte jusqu’au bout"},{"id":"d","texte":"Elles font oublier le courage de l’autrice pour son temps"}],"multiple":false}]}$ex$::jsonb,
