   $ex${"titre":"Que faire ?","competence":"analyser-texte","situation":"Voici un monologue écrit pour l’exercice. Les questions n’y servent pas toutes à demander quelque chose : apprends à nommer leur valeur.","documents":[{"id":"monolog","type":"texte","genre":"theatre","titre":"Clarisse devant la porte","blocs":[{"didascalie":"Clarisse, seule, hésite devant la porte de la maison."},{"personnage":"Clarisse","replique":"Que faire ? Partirai-je sans un mot, ou la regarderai-je en face ? Qui, demain, osera dire que j’ai eu tort ?"},{"didascalie":"Elle se tourne vers le public."},{"personnage":"Clarisse","replique":"Et vous, que feriez-vous à ma place ?"}],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Associe chaque question à sa valeur.","aide":"Une seule attend vraiment une réponse ; une seule est posée à soi-même.","type":"association","gauche":[{"id":"g0","texte":"Que faire ?"},{"id":"g1","texte":"Qui ne sait pas qu’un mensonge finit par se découvrir ?"},{"id":"g2","texte":"Quelle heure est-il ?"}],"droite":[{"id":"d0","texte":"Vraie question"},{"id":"d1","texte":"Délibération"},{"id":"d2","texte":"Question rhétorique"}]},{"enonce":"Quelle est la construction de « Partirai-je sans un mot ? » ?","aide":"Y a-t-il un mot interrogatif ? Comment le sujet est-il placé ?","type":"choix","options":[{"id":"a","texte":"Interrogation partielle, avec intonation seule"},{"id":"b","texte":"Interrogation totale, avec intonation seule"},{"id":"c","texte":"Interrogation totale, avec inversion sujet-verbe"},{"id":"d","texte":"Interrogation partielle, avec « est-ce que »"}],"multiple":false},{"enonce":"Que fait Clarisse quand elle se pose à elle-même ces questions au théâtre ?","aide":"Que ressent-on quand un personnage se demande « Que faire ? » ?","type":"choix","options":[{"id":"a","texte":"Elle dénonce un adversaire"},{"id":"b","texte":"Elle raconte ce qui s’est passé"},{"id":"c","texte":"Elle demande un renseignement au public"},{"id":"d","texte":"Elle donne à voir son hésitation"}],"multiple":false},{"enonce":"Remets dans l’ordre les trois étapes de l’analyse d’une interrogation à l’oral.","aide":"La valeur est ce qu’on dit en dernier.","type":"ordre","items":[{"id":"a","texte":"Repérer la construction"},{"id":"b","texte":"Nommer la valeur : vraie question, rhétorique, délibération"},{"id":"c","texte":"Repérer le type : totale ou partielle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"« Que faire ? » est une **délibération** ; la deuxième **n’attend pas de réponse** (tout le monde le sait) ; la troisième est une **vraie question**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pas de mot interrogatif : c’est une **interrogation totale**, construite par **inversion** du sujet (« partirai-je »)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dans un monologue, la délibération **donne à voir l’hésitation** du personnage."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Type, **construction**, puis **valeur** : c’est la troisième étape qui montre ce que tu sais lire."}]$ex$::jsonb),
  ('174f7797-f7e3-5700-b020-cb153fd04493'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le discours du délégué","competence":"argumenter","situation":"Un délégué de classe s’adresse à ses camarades dans un discours écrit pour l’exercice. Analyse ses questions comme à l’oral.","documents":[{"id":"disc","type":"texte","genre":"recit","titre":"Discours du délégué","blocs":["Élèves, amis, qui ne connaît pas l’état de notre lycée ? Est-ce que nous allons attendre encore un an ? Pourquoi ne pas agir dès aujourd’hui ? Serait-il raisonnable de nous taire ?"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Combien de ces quatre questions sont des interrogations partielles ?","aide":"Cherche les mots interrogatifs.","type":"nombre"},{"enonce":"Associe chaque question à son niveau de langue.","aide":"Regarde la construction : « est-ce que » ou inversion.","type":"association","gauche":[{"id":"g0","texte":"Est-ce que nous allons attendre encore un an ?"},{"id":"g1","texte":"Serait-il raisonnable de nous taire ?"}],"droite":[{"id":"d0","texte":"Soutenu"},{"id":"d1","texte":"Courant"}]},{"enonce":"Quelle est la valeur dominante de ces questions ?","aide":"Le délégué attend-il vraiment qu’on lui réponde ?","type":"choix","options":[{"id":"a","texte":"Des questions indirectes"},{"id":"b","texte":"De vraies questions qui cherchent des informations"},{"id":"c","texte":"Des questions rhétoriques qui n’attendent pas de réponse"},{"id":"d","texte":"Des délibérations intérieures"}],"multiple":false},{"enonce":"Quel est leur effet sur les camarades ?","aide":"Quelle réponse chacun est-il poussé à donner ?","type":"choix","options":[{"id":"a","texte":"Elles leur laissent entièrement le choix de leur propre conclusion"},{"id":"b","texte":"Elles leur apprennent des faits nouveaux qu’ils ne connaissaient pas"},{"id":"c","texte":"Elles ralentissent seulement le discours sans rien dire de plus"},{"id":"d","texte":"Elles guident l’auditoire vers la conclusion que le délégué souhaite"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Deux : « **Qui** ne connaît pas… » et « **Pourquoi** ne pas agir… ». Les deux autres sont totales."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"« Est-ce que » est **courant** ; l’inversion (« serait-il ») est **soutenue**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Ce sont des **questions rhétoriques** : elles affirment sous forme de questions."},{"cle":{"type":"choix","ids":["d"]},"explication":"La question rhétorique est une **arme majeure de l’argumentation** : elle entraîne l’adhésion."}]$ex$::jsonb),
  ('2ac12546-9e5b-5341-91d8-6162f898ec21'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Sara et Léo","competence":"manier-langue","situation":"Un petit récit rapporte des questions. Trouve ce qui les introduit, puis compare avec les questions posées directement.","documents":[{"id":"sara","type":"texte","genre":"recit","titre":"Un matin au collège","blocs":["Sara arrive au collège. Léo lui demande où elle habite. Elle se demande pourquoi il veut le savoir. Il ignore si elle sera à l’heure demain."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois verbes qui introduisent une question rapportée.","aide":"Ils signifient « poser » ou « ne pas savoir ».","type":"zone","document":"sara","multiple":true},{"enonce":"Range chaque phrase : interrogation directe ou indirecte ?","aide":"Cherche le point d’interrogation et l’inversion.","type":"categories","categories":[{"id":"c0","texte":"Directe"},{"id":"c1","texte":"Indirecte"}],"items":[{"id":"i0","texte":"Il ignore si elle sera à l’heure."},{"id":"i1","texte":"Pourquoi veut-il le savoir ?"},{"id":"i2","texte":"Où habites-tu ?"},{"id":"i3","texte":"Léo lui demande où elle habite."}]},{"enonce":"« Viendras-tu ? » devient « Je me demande ___ tu viendras. »","aide":"Une question totale passe par un petit mot.","type":"trous","segments":["Je me demande ",0," tu viendras."],"banque":["où","que","ce que","si"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m12","m19"]},"explication":"Les verbes introducteurs sont **demande**, **demande** (« se demande ») et **ignore**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"La **directe** garde point d’interrogation et inversion ; l’**indirecte** est une subordonnée sans ces signes."},{"cle":{"type":"trous","trous":[["si"]]},"affichage":"si","explication":"La question totale devient indirecte avec **si**."}]$ex$::jsonb),
  ('2ac12546-9e5b-5341-91d8-6162f898ec21'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"À la bibliothèque","competence":"manier-langue","situation":"Jules et Clara se croisent au CDI. Transforme leurs questions en interrogations indirectes, au passé.","documents":[{"id":"cdi","type":"dialogue","modele":"sms","participants":[{"nom":"Jules","emoji":"👦","cote":"gauche"},{"nom":"Clara","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Jules","texte":"Où vas-tu ?"},{"qui":"Clara","texte":"À la bibliothèque. Qu’est-ce que tu cherches ?"},{"qui":"Jules","texte":"Mon cahier. Est-ce que tu l’as vu ?"}]}],"questions":[{"enonce":"Complète : Jules a demandé à Clara où elle ___.","aide":"Le verbe introducteur est au passé : le présent devient imparfait.","type":"trous","segments":["Jules a demandé à Clara où elle ",0,"."]},{"enonce":"Comment Clara a-t-elle demandé à Jules ce qu’il cherchait, à l’indirect ?","aide":"« Qu’est-ce que » devient « ce que », et le temps s’accorde.","type":"choix","options":[{"id":"a","texte":"Elle lui a demandé ce qu’est-ce qu’il cherchait"},{"id":"b","texte":"Elle lui a demandé si il cherchait"},{"id":"c","texte":"Elle lui a demandé ce qu’il cherchait"},{"id":"d","texte":"Elle lui a demandé qu’est-ce qu’il cherche"}],"multiple":false},{"enonce":"Complète : Jules lui a demandé ___ elle l’___ vu.","aide":"« Est-ce que » devient « si » ; « tu l’as vu » se met au plus-que-parfait.","type":"trous","segments":["Jules lui a demandé ",0," elle l’",1," vu."],"banque":["ce que","si","a","avait","que"]},{"enonce":"Dans « Clara a demandé à Jules ce qu’il cherchait », quelle est la subordonnée ?","aide":"Que demande Clara ? Cette subordonnée répond à la question « quoi ? ».","type":"choix","options":[{"id":"a","texte":"Une circonstancielle de cause"},{"id":"b","texte":"Une relative qui complète un nom"},{"id":"c","texte":"Une interrogative indirecte, COD de « a demandé »"},{"id":"d","texte":"Une complétive introduite par « que » sujet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["allait"]]},"affichage":"allait","explication":"« Où vas-tu ? » devient « où elle **allait** » : personne et temps changent."},{"cle":{"type":"choix","ids":["c"]},"explication":"« Qu’est-ce que tu cherches ? » → « **ce qu’il cherchait** »."},{"cle":{"type":"trous","trous":[["si"],["avait"]]},"affichage":"si · avait","explication":"« Est-ce que tu l’as vu ? » → « **si** elle l’**avait** vu »."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est une **interrogative indirecte**, COD du verbe introducteur « a demandé »."}]$ex$::jsonb),
