   $ex${"titre":"Deux manières de rapporter","competence":"analyser-texte","situation":"Voici la même scène racontée de deux façons (textes écrits pour l’exercice). Compare la voix du colonel dans l’une et dans l’autre.","documents":[{"id":"dir","type":"texte","genre":"recit","titre":"Version A : discours direct","blocs":["Alors le colonel se tourna vers le lieutenant : « Qui a donné cet ordre ? Pourquoi n’ai-je pas été prévenu ? »"],"source":"Texte écrit pour l’exercice"},{"id":"ind","type":"texte","genre":"recit","titre":"Version B : discours indirect","blocs":["Alors le colonel demanda au lieutenant qui avait donné cet ordre et pourquoi il n’avait pas été prévenu."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans la version B, touche les deux mots interrogatifs.","aide":"Ils étaient déjà là dans la version A.","type":"zone","document":"ind","multiple":true},{"enonce":"Range chaque élément : disparaît, change ou reste identique à l’indirect ?","aide":"Compare mot à mot les deux versions.","type":"categories","categories":[{"id":"c0","texte":"Disparaît"},{"id":"c1","texte":"Change"},{"id":"c2","texte":"Reste identique"}],"items":[{"id":"i0","texte":"L’inversion du sujet (« ai-je »)"},{"id":"i1","texte":"Le point d’interrogation"},{"id":"i2","texte":"Le mot « pourquoi »"},{"id":"i3","texte":"Le mot « qui »"},{"id":"i4","texte":"Le temps du verbe (« ai été » devient « avait été »)"}]},{"enonce":"Quel effet produit la version B ?","aide":"Dans laquelle entend-on le colonel parler ?","type":"choix","options":[{"id":"a","texte":"Elle rend la scène plus vivante en donnant la parole directe au colonel"},{"id":"b","texte":"Elle transforme les questions du colonel en ordres adressés au lecteur"},{"id":"c","texte":"Elle accélère l’action en supprimant tous les verbes de la phrase"},{"id":"d","texte":"Elle efface la voix du colonel et met le narrateur entre lui et le lecteur"}],"multiple":false},{"enonce":"Complète : dans la version B, le narrateur se place ___ le lecteur et la parole du colonel.","aide":"Le narrateur sert d’intermédiaire.","type":"trous","segments":["Dans la version B, le narrateur se place ",0," le lecteur et la parole du colonel."],"banque":["devant","entre","contre","avec"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m12"]},"explication":"Les mots interrogatifs **qui** et **pourquoi** ne changent pas à l’indirect."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c2","i3":"c2","i4":"c1"}},"explication":"Le point d’interrogation et l’inversion **disparaissent**, le temps et la personne **changent**, « qui » et « pourquoi » **restent**."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’indirect **efface la voix** du personnage : on n’entend plus le colonel, on entend le narrateur."},{"cle":{"type":"trous","trous":[["entre"]]},"affichage":"entre","explication":"Le narrateur se place **entre** le lecteur et la parole : il prend de la distance, parfois de l’ironie."}]$ex$::jsonb),
