   $ex${"titre":"Le village endormi","competence":"analyser-texte","situation":"Dans un court texte, plusieurs mots viennent se glisser après « ne ». Repère-les, puis distingue les formes particulières de négation.","documents":[{"id":"vill","type":"texte","genre":"recit","titre":"Le village endormi","blocs":["Le village ne dort plus. Personne n’ose sortir et l’on n’entend guère que le vent. Jamais la nuit ne fut si longue."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre mots qui forment la négation avec « ne ».","aide":"Ils complètent « ne » comme « pas » le fait.","type":"zone","document":"vill","multiple":true},{"enonce":"Associe chaque forme à son exemple.","aide":"Pense au piège : une forme négative qui ne nie pas.","type":"association","gauche":[{"id":"g0","texte":"Négation exceptive"},{"id":"g1","texte":"Négation lexicale"},{"id":"g2","texte":"Négation à un seul terme"},{"id":"g3","texte":"« Ne » explétif"}],"droite":[{"id":"d0","texte":"Je crains qu’il ne pleuve."},{"id":"d1","texte":"Un geste inhumain"},{"id":"d2","texte":"Il n’a que deux amis."},{"id":"d3","texte":"Je ne saurais dire"}]},{"enonce":"Que signifie « Il n’a que deux amis » ?","aide":"« Ne… que » équivaut à un autre adverbe.","type":"choix","options":[{"id":"a","texte":"Il n’a pas deux amis"},{"id":"b","texte":"Il n’a aucun ami"},{"id":"c","texte":"Il a seulement deux amis"},{"id":"d","texte":"Il a plus de deux amis"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m5","m14","m18"]},"explication":"Les seconds termes sont **plus**, **Personne**, **guère** et **Jamais**."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"L’exceptive a **forme** de négation et **sens** de restriction ; la lexicale porte son sens négatif dans le mot ; l’explétif ne nie rien."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Il a seulement deux amis** : c’est une restriction, pas une négation."}]$ex$::jsonb),
  ('2db15f5d-3fc8-5ecc-ae8e-9d64fc381800'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le portrait de monsieur Varin","competence":"analyser-texte","situation":"Un portrait écrit pour l’exercice peint un homme par ce qui lui manque. Repère les négations, puis trie des phrases.","documents":[{"id":"varin","type":"texte","genre":"recit","titre":"Monsieur Varin","blocs":["Monsieur Varin ne dit rien, ne demande rien, n’attend plus personne. Il vit sans lumière dans un silence inhumain."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots dont le sens négatif est porté par le mot lui-même (négation lexicale).","aide":"Un mot sans « ne », et un adjectif commençant par un préfixe négatif.","type":"zone","document":"varin","multiple":true},{"enonce":"Complète : le portrait est construit par ___ : on définit l’homme par ce qui lui manque.","aide":"On retire au lieu d’ajouter.","type":"trous","segments":["Le portrait est construit par ",0," : on définit l’homme par ce qui lui manque."],"banque":["soustraction","addition","exagération","comparaison"]},{"enonce":"Range chaque phrase : négation totale, négation partielle ou restriction ?","aide":"Demande-toi ce qui est nié : toute la phrase, un élément, ou rien.","type":"categories","categories":[{"id":"c0","texte":"Négation totale"},{"id":"c1","texte":"Négation partielle"},{"id":"c2","texte":"Restriction (pas une négation)"}],"items":[{"id":"i0","texte":"Il n’a que dix euros."},{"id":"i1","texte":"Elle ne chante que le soir."},{"id":"i2","texte":"Ils ne viennent jamais en hiver."},{"id":"i3","texte":"Je ne suis pas content."},{"id":"i4","texte":"Elle ne chante pas."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m19"]},"explication":"Ce sont **sans** et **inhumain** : le sens négatif est dans le mot."},{"cle":{"type":"trous","trous":[["soustraction"]]},"affichage":"soustraction","explication":"Une accumulation de négations donne un portrait **par soustraction**, qui peint le vide."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c1","i3":"c0","i4":"c0"}},"explication":"« Ne… pas » nie toute la phrase ; « jamais en hiver » nie un élément ; « ne… que » **restreint**."}]$ex$::jsonb),
  ('2db15f5d-3fc8-5ecc-ae8e-9d64fc381800'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un texte qui disqualifie","competence":"analyser-texte","situation":"Dans un pamphlet écrit pour l’exercice, les négations servent à attaquer. Distingue les formes et leurs effets.","documents":[{"id":"pamph","type":"texte","genre":"recit","titre":"Contre ce prétendu progrès","blocs":["Ce prétendu progrès est inutile, inacceptable, inhumain. Ceux qui l’approuvent ne voient rien, ne savent rien, et n’ont qu’une idée : se taire."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois adjectifs qui portent une négation dans leur sens (négation lexicale).","aide":"Ils commencent par un préfixe négatif.","type":"zone","document":"pamph","multiple":true},{"enonce":"Quel effet produisent ces négations lexicales en série ?","aide":"L’auteur dit-il « non » ou qualifie-t-il ?","type":"choix","options":[{"id":"a","texte":"Elles adoucissent le propos pour ménager le lecteur"},{"id":"b","texte":"Elles accélèrent le récit en multipliant les faits"},{"id":"c","texte":"Elles disqualifient sans avoir l’air de nier"},{"id":"d","texte":"Elles marquent l’hésitation de celui qui parle"}],"multiple":false},{"enonce":"Touche le mot qui marque la restriction dans « n’ont qu’une idée ».","aide":"Quelle est la forme qui ressemble à une négation sans en être une ?","type":"zone","document":"pamph","multiple":false},{"enonce":"Que fait cette exceptive dans le texte ?","aide":"« N’ont qu’une idée » veut dire « ont seulement une idée ».","type":"choix","options":[{"id":"a","texte":"Elle resserre l’attention sur une seule chose"},{"id":"b","texte":"Elle fait oublier le reste du portrait"},{"id":"c","texte":"Elle nie toute la phrase"},{"id":"d","texte":"Elle marque une question"}],"multiple":false}]}$ex$::jsonb,
