  ('bb864e16-b8f5-59ea-b4d4-1fa635c956c5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le voyageur et les vitres","competence":"argumenter","situation":"Un visiteur venu d’ailleurs décrit notre monde dans une lettre écrite pour l’exercice. Que dénonce-t-il, et comment ?","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un voyageur","blocs":["Ici, chacun porte à la main une petite vitre qu’il ne cesse de regarder. Les gens marchent côte à côte sans se parler, fascinés par leur vitre. Ils m’assurent qu’elle les rapproche. Je les crois volontiers : c’est sans doute pourquoi ils se tiennent si près les uns des autres sans jamais s’adresser un mot."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Comment s’appelle ce procédé où un étranger décrit la société ?","aide":"Ce que l’habitude rend invisible devient étrange vu du dehors.","type":"choix","options":[{"id":"a","texte":"L’apologue didactique"},{"id":"b","texte":"La maxime universelle"},{"id":"c","texte":"Le regard éloigné"},{"id":"d","texte":"La gradation ascendante"}],"multiple":false},{"enonce":"Touche les deux mots qui montrent que les gens sont captivés par leur vitre.","aide":"Un verbe, puis un participe-adjectif.","type":"zone","document":"lettre","multiple":true},{"enonce":"Range chaque moyen d’agir : convaincre, persuader ou délibérer ?","aide":"Raison, émotions, jugement.","type":"categories","categories":[{"id":"c0","texte":"Convaincre"},{"id":"c1","texte":"Persuader"},{"id":"c2","texte":"Délibérer"}],"items":[{"id":"i0","texte":"Thèse, arguments et exemples"},{"id":"i1","texte":"Dialogue ouvert qui ne tranche pas d’avance"},{"id":"i2","texte":"Faire rire d’un travers par l’ironie"},{"id":"i3","texte":"Peser le pour et le contre"},{"id":"i4","texte":"Connecteurs logiques"},{"id":"i5","texte":"Apostrophe, image et rythme"}]},{"enonce":"Pourquoi l’auteur passe-t-il par une lettre fictive plutôt que par un essai ?","aide":"Quel avantage a le détour de la fiction ?","type":"choix","options":[{"id":"a","texte":"La lettre est plus courte qu’un essai et donc plus facile à lire"},{"id":"b","texte":"L’argumentation indirecte se retient mieux et échappe à la censure"},{"id":"c","texte":"La fiction n’a pas de thèse : elle ne fait que divertir le lecteur"},{"id":"d","texte":"Un essai serait toujours interdit et jamais publié à cette époque"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"C’est **le regard éloigné** (le Persan, le Huron…), procédé maître de l’argumentation indirecte."},{"cle":{"type":"zone","ids":["m14","m24"]},"explication":"Les mots sont **regarder** et **fascinés** : l’auteur dénonce une attention captive."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c2","i4":"c0","i5":"c1"}},"explication":"**Convaincre** vise la raison, **persuader** les émotions, **délibérer** le jugement."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’argumentation **indirecte** échappe plus facilement à la censure et se retient mieux."}]$ex$::jsonb),
  ('bb864e16-b8f5-59ea-b4d4-1fa635c956c5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Portrait d’un moraliste","competence":"analyser-texte","situation":"Un portrait bref, dans le goût des moralistes, est écrit pour l’exercice. Replace-le dans l’histoire des idées et analyse sa technique.","documents":[{"id":"mom","type":"tableau","titre":"Trois moments","colonnes":["Moment","Sa posture"],"lignes":[["Humanisme (XVIe)","Examen critique de tout"],["Âge classique (XVIIe)","Observer l’homme en société, forme brève"],["Lumières (XVIIIe)","La raison contre les préjugés"]],"enteteLignes":true},{"id":"clit","type":"texte","genre":"recit","titre":"Portrait de Clitandre","blocs":["Clitandre parle de tout et n’écoute personne ; il a mille amis à table et pas un seul au malheur."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Associe chaque moment à sa posture.","aide":"Reprends le tableau du document 1.","type":"association","gauche":[{"id":"g0","texte":"Humanisme"},{"id":"g1","texte":"Âge classique"},{"id":"g2","texte":"Lumières"}],"droite":[{"id":"d0","texte":"Examen critique de tout"},{"id":"d1","texte":"La raison contre les préjugés"},{"id":"d2","texte":"Observer l’homme en société, forme brève et ciselée"}]},{"enonce":"Touche les deux mots qui s’opposent dans la dernière phrase du portrait.","aide":"Un grand nombre, puis l’absence.","type":"zone","document":"clit","multiple":true},{"enonce":"À quel moment rattacher ce portrait bref et ciselé ?","aide":"Quelle forme brève les moralistes du XVIIe siècle aiment-ils ?","type":"choix","options":[{"id":"a","texte":"À aucun moment : le portrait est hors du temps"},{"id":"b","texte":"Aux Lumières, celles du XVIIIe siècle"},{"id":"c","texte":"À l’humanisme de la Renaissance, au XVIe siècle"},{"id":"d","texte":"À l’âge classique, celui des moralistes"}],"multiple":false},{"enonce":"Quelle est la visée de ce portrait ?","aide":"Contre qui ou contre quoi l’auteur écrit-il ?","type":"choix","options":[{"id":"a","texte":"Enseigner une technique de métier à un apprenti"},{"id":"b","texte":"Faire voter une loi pour corriger ce travers"},{"id":"c","texte":"Ridiculiser un travers social pour faire réfléchir"},{"id":"d","texte":"Raconter une histoire d’amitié entre deux personnages"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Humanisme : critique de tout ; classique : l’homme en société ; Lumières : la raison contre les préjugés."},{"cle":{"type":"zone","ids":["m10","m17"]},"explication":"**mille** s’oppose à **seul** : c’est une antithèse."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un portrait bref et ciselé qui observe l’homme en société est typique de **l’âge classique**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Chaque outil doit se rattacher à une visée : ici, **ridiculiser** un travers pour faire réfléchir."}]$ex$::jsonb),
  ('857bb35f-c934-5383-a0b9-b42dd295d324'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le colosse et son socle","competence":"analyser-texte","situation":"Ce passage, adapté pour l’exercice, contient l’image la plus célèbre du Discours. Lis-le, puis repère ce qu’il demande.","documents":[{"id":"colosse","type":"texte","genre":"source","titre":"Ne plus le soutenir","blocs":["« Soyez résolus de ne servir plus, et vous voilà libres. Je ne veux pas que vous le poussiez ni que vous l’ébranliez ; seulement ne le soutenez plus, et vous le verrez, comme un grand colosse dont on a dérobé la base, tomber de son propre poids et se rompre. »"],"source":"D’après La Boétie, Discours de la servitude volontaire (vers 1548) — texte adapté"}],"questions":[{"enonce":"Touche les deux verbes à l’impératif.","aide":"Un verbe d’état, puis un verbe d’appui.","type":"zone","document":"colosse","multiple":true},{"enonce":"Que propose La Boétie pour se libérer du tyran ?","aide":"Relis la phrase qui dit ce qu’il ne veut pas.","type":"choix","options":[{"id":"a","texte":"Attendre qu’un tyran plus doux lui succède"},{"id":"b","texte":"Cesser de le soutenir, sans violence ni révolte armée"},{"id":"c","texte":"Lever une armée et le combattre par les armes"},{"id":"d","texte":"Le pousser et l’ébranler jusqu’à sa chute"}],"multiple":false},{"enonce":"Associe chaque image ou élément à ce qu’il dit.","aide":"Chaque image dit une cause ou une conséquence.","type":"association","gauche":[{"id":"g0","texte":"Le colosse dont on retire la base"},{"id":"g1","texte":"Le joug que l’on croit naturel"},{"id":"g2","texte":"« Cinq ou six », puis six cents, puis six mille"},{"id":"g3","texte":"Les jeux et les fêtes"}],"droite":[{"id":"d0","texte":"Le divertissement qui endort"},{"id":"d1","texte":"Le tyran tombe dès qu’on cesse de le soutenir"},{"id":"d2","texte":"L’habitude de servir"},{"id":"d3","texte":"La chaîne des complices"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m26"]},"explication":"Les impératifs sont **Soyez** et **soutenez** : le texte donne un ordre simple."},{"cle":{"type":"choix","ids":["b"]},"explication":"Il suffit de **retirer son consentement** : ni bataille, ni armes."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"Colosse : le tyran dépend de ceux qui le soutiennent ; joug : habitude ; chaîne : complices ; fêtes : divertissement."}]$ex$::jsonb),
  ('857bb35f-c934-5383-a0b9-b42dd295d324'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La pyramide des complices","competence":"observer-schema","situation":"La Boétie explique que la tyrannie tient par une chaîne d’intérêts. Observe le schéma, puis classe les ressorts de l’obéissance.","documents":[{"id":"pyr","type":"schema","titre":"La chaîne des complices","largeur":320,"hauteur":230,"elements":[{"forme":"rect","x":110,"y":20,"l":100,"h":34,"arrondi":6,"texte":"Le tyran","id":"z1","zone":true},{"forme":"rect","x":80,"y":68,"l":160,"h":34,"arrondi":6,"texte":"Cinq ou six","id":"z2","zone":true},{"forme":"rect","x":50,"y":116,"l":220,"h":34,"arrondi":6,"texte":"Six cents","id":"z3","zone":true},{"forme":"rect","x":20,"y":164,"l":280,"h":34,"arrondi":6,"texte":"Six mille","id":"z4","zone":true},{"forme":"texte","x":160,"y":218,"texte":"Chacun profite de celui qui est au-dessus","taille":"petit","italique":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Touche le groupe qui profite directement du tyran et le soutient de près.","aide":"Il se trouve juste sous le tyran.","type":"zone","document":"pyr","multiple":false},{"enonce":"Range chaque trait parmi les ressorts de l’obéissance.","aide":"Trois ressorts : habitude, divertissement, complices.","type":"categories","categories":[{"id":"c0","texte":"L’habitude"},{"id":"c1","texte":"Le divertissement"},{"id":"c2","texte":"La chaîne des complices"}],"items":[{"id":"i0","texte":"Une pyramide d’intérêts"},{"id":"i1","texte":"Jeux, théâtres, fêtes, distributions de blé"},{"id":"i2","texte":"Cinq ou six en profitent, puis six cents"},{"id":"i3","texte":"Le pouvoir amuse ceux qu’il dépouille"},{"id":"i4","texte":"« La première raison, c’est la coutume »"},{"id":"i5","texte":"On naît sous le joug et on le croit naturel"}]},{"enonce":"Pourquoi la chaîne des complices est-elle la plus redoutable ?","aide":"Qui travaille pour le tyran dans le schéma ?","type":"choix","options":[{"id":"a","texte":"Elle fait tenir l’édifice sans que le tyran ait à agir"},{"id":"b","texte":"Elle supprime l’habitude et la peur chez les sujets"},{"id":"c","texte":"Elle se limite à cinq ou six personnes autour du tyran"},{"id":"d","texte":"Elle dépend du hasard et non de l’intérêt de chacun"}],"multiple":false},{"enonce":"Quel renversement La Boétie opère-t-il ?","aide":"La question habituelle est « comment le tyran tient-il le peuple ? ».","type":"choix","options":[{"id":"a","texte":"Il demande comment le tyran punit"},{"id":"b","texte":"Il demande comment limiter le pouvoir des nobles"},{"id":"c","texte":"Il demande comment le peuple tient le tyran"},{"id":"d","texte":"Il demande qui paie les impôts"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Ce sont **les cinq ou six** qui profitent directement du tyran ; six cents profitent à leur tour d’eux, puis six mille."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c1","i4":"c0","i5":"c0"}},"explication":"La coutume est l’**habitude** ; fêtes et jeux sont le **divertissement** ; la pyramide est la **chaîne des complices**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une **pyramide d’intérêts** fait tenir l’édifice sans que le tyran ait à agir."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il demande : **comment le peuple tient-il le tyran ?** La domination est consentie."}]$ex$::jsonb),
  ('857bb35f-c934-5383-a0b9-b42dd295d324'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un maître sans clés","competence":"argumenter","situation":"Un texte écrit pour l’exercice, à la manière de La Boétie, sert de point de départ pour analyser la thèse et les moyens de l’auteur.","documents":[{"id":"ren","type":"tableau","titre":"Le renversement","colonnes":["La question habituelle","La question de La Boétie"],"lignes":[["Comment le tyran tient-il le peuple ?","Comment le peuple tient-il le tyran ?"]],"enteteLignes":true},{"id":"maitre","type":"texte","genre":"recit","titre":"Le maître et ses clés","blocs":["Vous vous plaignez du maître, et pourtant c’est vous qui lui portez ses bagages.","Que peut-il, seul, contre vous tous ? Rien.","Chaque matin, c’est encore vous qui lui tendez ses clés."],"source":"Texte écrit pour l’exercice, à la manière du Discours"}],"questions":[{"enonce":"Touche les deux verbes qui montrent que les « vous » aident le maître.","aide":"Deux gestes de service.","type":"zone","document":"maitre","multiple":true},{"enonce":"Que fait la question « Que peut-il, seul, contre vous tous ? »","aide":"Le texte répond lui-même juste après.","type":"choix","options":[{"id":"a","texte":"C’est une vraie question, qui cherche une information"},{"id":"b","texte":"C’est une question indirecte"},{"id":"c","texte":"C’est une question rhétorique : la réponse est « rien »"},{"id":"d","texte":"C’est une délibération du maître"}],"multiple":false},{"enonce":"Range chaque élément : cause de l’obéissance ou remède ?","aide":"Les causes maintiennent le tyran ; les remèdes le retirent.","type":"categories","categories":[{"id":"c0","texte":"Cause de l’obéissance"},{"id":"c1","texte":"Remède"}],"items":[{"id":"i0","texte":"Refuser de soutenir le tyran, sans le combattre"},{"id":"i1","texte":"Retirer son consentement"},{"id":"i2","texte":"La coutume"},{"id":"i3","texte":"Se résoudre à ne plus servir"},{"id":"i4","texte":"Les jeux et les fêtes"},{"id":"i5","texte":"La chaîne des complices"}]},{"enonce":"Pourquoi le texte a-t-il servi à tous les camps ?","aide":"Qui détient le pouvoir, selon la thèse ?","type":"choix","options":[{"id":"a","texte":"Il défend la monarchie absolue et l’obéissance au roi"},{"id":"b","texte":"Il déplace la responsabilité politique du tyran vers le peuple"},{"id":"c","texte":"Il refuse toute politique et conseille de se retirer du monde"},{"id":"d","texte":"Il donne un plan de bataille précis pour renverser un roi"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m30"]},"explication":"**portez** et **tendez** : les sujets donnent eux-mêmes au maître sa force."},{"cle":{"type":"choix","ids":["c"]},"explication":"Question **rhétorique** : le texte répond « Rien », ce qui renforce la thèse."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"La coutume, les fêtes et la chaîne des complices **maintiennent** le tyran ; retirer son consentement est le **remède**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Il **déplace la responsabilité politique** du tyran vers le peuple : chaque camp peut s’en servir."}]$ex$::jsonb),
  ('1dc17334-17d3-5e0e-a23c-d9805ad384c2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La marquise et le vaisseau","competence":"analyser-texte","situation":"Dans ce dialogue écrit pour l’exercice, à la manière de Fontenelle, une marquise objecte et le philosophe répond par une image.","documents":[{"id":"dial","type":"texte","genre":"theatre","titre":"Soirée dans le parc","blocs":[{"didascalie":"La marquise et le philosophe regardent le ciel."},{"personnage":"La marquise","replique":"Comment la Terre tournerait-elle sans que je le sente ?"},{"personnage":"Le philosophe","replique":"Madame, vous êtes sur la Terre comme sur un vaisseau : il avance, et vous ne sentez rien."}],"source":"Texte écrit pour l’exercice, à la manière de Fontenelle"}],"questions":[{"enonce":"Associe chaque élément à son rôle.","aide":"Chaque élément sert la vulgarisation.","type":"association","gauche":[{"id":"g0","texte":"La marquise"},{"id":"g1","texte":"Le philosophe"},{"id":"g2","texte":"L’image du vaisseau"},{"id":"g3","texte":"Le ton galant"}],"droite":[{"id":"d0","texte":"Toucher un public mondain"},{"id":"d1","texte":"Elle pose les objections du lecteur"},{"id":"d2","texte":"Rendre sensible un mouvement qu’on ne sent pas"},{"id":"d3","texte":"Il explique pas à pas"}]},{"enonce":"Touche le mot qui annonce la comparaison.","aide":"Un petit mot de comparaison.","type":"zone","document":"dial","multiple":false},{"enonce":"À quoi sert l’objection de la marquise ?","aide":"Qui se reconnaît dans ses questions ?","type":"choix","options":[{"id":"a","texte":"Elle montre que la marquise est ignorante"},{"id":"b","texte":"Elle contredit la science"},{"id":"c","texte":"Elle ralentit l’exposé"},{"id":"d","texte":"Elle est celle du lecteur, qui part de zéro"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"La marquise **représente le lecteur**, le philosophe **explique**, l’image **rend sensible**, le ton galant **touche un public mondain**."},{"cle":{"type":"zone","ids":["m23"]},"explication":"Le mot est **comme** : il relie la Terre au vaisseau."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les objections de la marquise sont **celles du lecteur** : le dialogue rend visible le chemin."}]$ex$::jsonb),
  ('1dc17334-17d3-5e0e-a23c-d9805ad384c2'::uuid, 2, 2, 10, 35, 4,
