  ('1dc17334-17d3-5e0e-a23c-d9805ad384c2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"L’horloge du philosophe","competence":"argumenter","situation":"Fontenelle explique l’univers par des images tirées du monde de la marquise. Étudie ces images, puis un passage imité pour l’exercice.","documents":[{"id":"images","type":"fiche","modele":"affiche","entete":"Quatre images de Fontenelle","sousTitre":"Le monde mondain au service de la science","emoji":"🔭","teinte":"violet","lignes":[{"texte":"Le spectacle d’opéra"},{"texte":"Le vaisseau"},{"texte":"L’horloge"},{"texte":"Les voisins"}],"pied":"Images"},{"id":"montre","type":"texte","genre":"recit","titre":"À la manière de Fontenelle","blocs":["Regardez cette montre : on voit l’aiguille qui court, mais on ne voit pas les rouages. Le philosophe est celui qui ouvre le boîtier."],"source":"Texte écrit pour l’exercice, à la manière de Fontenelle"}],"questions":[{"enonce":"Associe chaque image à ce qu’elle explique.","aide":"Chaque image traduit une idée scientifique.","type":"association","gauche":[{"id":"g0","texte":"Le spectacle d’opéra"},{"id":"g1","texte":"Le vaisseau"},{"id":"g2","texte":"L’horloge"},{"id":"g3","texte":"Les voisins"}],"droite":[{"id":"d0","texte":"Le mouvement qu’on ne sent pas"},{"id":"d1","texte":"Le philosophe cherche les machines et les cordes derrière le décor"},{"id":"d2","texte":"Un mécanisme réglé"},{"id":"d3","texte":"Des mondes qu’on n’a pas encore visités"}]},{"enonce":"Dans le passage imité, touche ce qui joue le rôle des machines cachées derrière le décor.","aide":"On voit l’aiguille, pas… quoi ?","type":"zone","document":"montre","multiple":false},{"enonce":"Pourquoi Fontenelle choisit-il des images du monde mondain ?","aide":"À qui s’adresse-t-il ?","type":"choix","options":[{"id":"a","texte":"Pour cacher la science aux savants qui la connaissent déjà"},{"id":"b","texte":"Pour expliquer une notion difficile par une image familière à la marquise"},{"id":"c","texte":"Pour se moquer de l’ignorance de la marquise devant le lecteur"},{"id":"d","texte":"Pour éviter d’avoir à parler d’astronomie devant une femme du monde"}],"multiple":false},{"enonce":"Que répondre à « rendre accessible, c’est déformer » ?","aide":"Quelles sont les deux réponses de Fontenelle ?","type":"choix","options":[{"id":"a","texte":"Il faut renoncer à vulgariser, car expliquer revient toujours à déformer"},{"id":"b","texte":"Le dialogue donne la parole aux objections et la prudence évite d’asséner"},{"id":"c","texte":"Un ton galant rend forcément la science fausse, donc inutile à lire"},{"id":"d","texte":"Seuls les savants doivent lire ces textes, pas les gens du monde"}],"multiple":false}]}$ex$::jsonb,
