   $ex${"titre":"Le regard de Zilia","competence":"analyser-texte","situation":"Zilia décrit la société française comme si tout y était étrange. Étudie ce regard avec un passage imité pour l’exercice.","documents":[{"id":"enigmes","type":"tableau","titre":"Objet devenu énigme","colonnes":["Objet décrit","Ce qu’il dévoile"],"lignes":[["Les miroirs et les carrosses","La vanité"],["Les rites religieux","L’hypocrisie"],["La politesse mondaine","La superficialité"],["L’éducation des femmes","Des ornements, sans savoir"]],"enteteLignes":true},{"id":"salon","type":"texte","genre":"lettre","titre":"Une lettre à la manière de Zilia","blocs":["Hier, on m’a menée dans une grande salle où des hommes et des femmes marchaient en rond. Ils parlaient beaucoup et ne disaient rien ; ils riaient, mais leurs yeux restaient graves. On m’a dit que c’était un divertissement."],"source":"Texte écrit pour l’exercice, à la manière de Zilia"}],"questions":[{"enonce":"Associe chaque objet devenu énigme à ce qu’il dévoile.","aide":"Reprends le document 1.","type":"association","gauche":[{"id":"g0","texte":"Les miroirs et les carrosses"},{"id":"g1","texte":"Les rites religieux"},{"id":"g2","texte":"La politesse mondaine"},{"id":"g3","texte":"L’éducation des femmes"}],"droite":[{"id":"d0","texte":"L’hypocrisie"},{"id":"d1","texte":"La vanité"},{"id":"d2","texte":"Des ornements, sans savoir"},{"id":"d3","texte":"La superficialité"}]},{"enonce":"Touche les deux mots qui s’opposent dans « Ils parlaient… et ne disaient… ».","aide":"Une quantité, puis un néant.","type":"zone","document":"salon","multiple":true},{"enonce":"Pourquoi Zilia peut-elle tout décrire sans l’excuse de l’habitude ?","aide":"Que change le fait de ne rien comprendre ?","type":"choix","options":[{"id":"a","texte":"Elle connaît déjà bien la France et ses usages depuis l’enfance"},{"id":"b","texte":"Elle ne comprend rien à leurs usages et les voit donc de l’extérieur"},{"id":"c","texte":"Elle écrit pour les flatter et gagner la faveur de Déterville"},{"id":"d","texte":"Elle les approuve tous car elle les juge naturels et raisonnables"}],"multiple":false},{"enonce":"Sur quoi Zilia écrit-elle d’abord ses lettres ?","aide":"Elle ne connaît pas encore le français.","type":"choix","options":[{"id":"a","texte":"Sur des feuilles de palmier séchées"},{"id":"b","texte":"Sur des tablettes de cire gravées au stylet"},{"id":"c","texte":"Sur des quipus, des cordelettes nouées"},{"id":"d","texte":"Sur du parchemin, à la plume d’oie"}],"multiple":false}]}$ex$::jsonb,
