   $ex$[{"cle":{"type":"zone","ids":["m2","m5","m8","m9"]},"explication":"**montait**, **chantaient**, **s’éveillait** : trois propositions."},{"cle":{"type":"choix","ids":["b"]},"explication":"Il n’y a pas de mot de liaison : c’est de la **juxtaposition**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Les conjonctions sont **mais, ou, et, donc, or, ni, car** ; les autres sont des **adverbes de liaison**."}]$ex$::jsonb),
