   $ex${"titre":"Un livre à rendre","competence":"analyser-texte","situation":"Un court récit écrit pour l’exercice mêle juxtaposition et coordination. Analyse-le comme à l’oral.","documents":[{"id":"livre","type":"texte","genre":"recit","titre":"Zoé sort","blocs":["Il pleuvait, mais Zoé sortit : elle devait rendre ce livre, car la bibliothèque fermait à midi."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux conjonctions de coordination.","aide":"Deux mots de la liste « mais, ou, et, donc, or, ni, car ».","type":"zone","document":"livre","multiple":true},{"enonce":"Associe chaque mot de liaison au rapport qu’il exprime.","aide":"Pluie / sortie ; sortie / fermeture.","type":"association","gauche":[{"id":"g0","texte":"mais"},{"id":"g1","texte":"car"}],"droite":[{"id":"d0","texte":"Cause"},{"id":"d1","texte":"Opposition"}]},{"enonce":"Pour subordonner la cause avec une conjonction de subordination : Zoé devait rendre ce livre ___ la bibliothèque fermait à midi.","aide":"Il faut une conjonction de subordination, pas de coordination.","type":"trous","segments":["Zoé devait rendre ce livre ",0," la bibliothèque fermait à midi."],"banque":["donc","mais","or","parce que"]},{"enonce":"Quel lien le deux-points établit-il entre « Zoé sortit » et « elle devait rendre ce livre » ?","aide":"Il n’y a pas de conjonction.","type":"choix","options":[{"id":"a","texte":"Une coordination, le deux-points jouant le rôle d’un « et »"},{"id":"b","texte":"Une phrase simple, puisque la ponctuation ne relie rien"},{"id":"c","texte":"Une subordination, le deux-points introduisant une cause"},{"id":"d","texte":"Une juxtaposition, au lecteur de comprendre le lien"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m10"]},"explication":"Ce sont **mais** et **car**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"« Mais » oppose la pluie à la sortie ; « car » donne la **cause** du départ."},{"cle":{"type":"trous","trous":[["parce que"]]},"affichage":"parce que","explication":"**parce que** subordonne ; **car** coordonne : c’est la distinction la plus demandée à l’oral."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le deux-points juxtapose : le lien de **cause** est implicite."}]$ex$::jsonb),
  ('e1bc8318-64df-5245-9fef-fd77e0c21bbb'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Vite ou posément","competence":"analyser-texte","situation":"Deux textes écrits pour l’exercice n’ont pas le même rythme. Compare, puis associe effets et contextes.","documents":[{"id":"vite","type":"texte","genre":"recit","titre":"Texte A : un récit","blocs":["Le chien aboya, la porte claqua, les enfants coururent, la nuit tomba."],"source":"Texte écrit pour l’exercice"},{"id":"pose","type":"texte","genre":"recit","titre":"Texte B : un discours","blocs":["Nous sommes fatigués, cependant nous avançons ; nous avons peur, pourtant nous avançons."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Associe chaque contexte à l’effet de la juxtaposition.","aide":"Un effet par contexte.","type":"association","gauche":[{"id":"g0","texte":"Dans un récit"},{"id":"g1","texte":"Dans une description"},{"id":"g2","texte":"Dans un discours"}],"droite":[{"id":"d0","texte":"Elle accélère l’action"},{"id":"d1","texte":"Elle marque l’émotion qui bouscule la syntaxe"},{"id":"d2","texte":"Elle entasse les détails"}]},{"enonce":"Dans le texte B, touche les deux adverbes de liaison.","aide":"Ils marquent une opposition et peuvent se déplacer.","type":"zone","document":"pose","multiple":true},{"enonce":"Quel rapport logique exprime « cependant » dans le texte B ?","aide":"La fatigue devrait arrêter, mais…","type":"choix","options":[{"id":"a","texte":"L’opposition"},{"id":"b","texte":"La conséquence"},{"id":"c","texte":"Le but"},{"id":"d","texte":"La cause"}],"multiple":false},{"enonce":"Quel effet produit cette coordination adversative, à l’inverse du texte A ?","aide":"Pense au mot « contrôlé ».","type":"choix","options":[{"id":"a","texte":"Elle marque un raisonnement contrôlé"},{"id":"b","texte":"Elle supprime les détails"},{"id":"c","texte":"Elle indique un simple dialogue"},{"id":"d","texte":"Elle accélère l’action"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Récit : **accélération** ; description : **accumulation** ; discours : **émotion**."},{"cle":{"type":"zone","ids":["m3","m9"]},"explication":"Ce sont **cependant** et **pourtant** : des adverbes de liaison, pas des conjonctions."},{"cle":{"type":"choix","ids":["a"]},"explication":"« Cependant » oppose la fatigue et le fait d’avancer : c’est une coordination **adversative**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La coordination adversative (*mais*, *pourtant*) marque au contraire **un raisonnement contrôlé**."}]$ex$::jsonb),
  ('81b236ab-9380-5a11-9761-727d157acd9f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois pronoms, trois rôles","competence":"manier-langue","situation":"Tu prépares la question de grammaire de ton oral. Trois phrases courtes, trois pronoms relatifs : repère-les, puis dis le rôle de chacun.","documents":[{"id":"phr","type":"texte","genre":"source","titre":"Trois phrases","blocs":["La cousine qui habite à Lyon nous rend visite.","Le film que nous avons vu hier durait trois heures.","Voici la salle où se déroule l’oral."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les trois pronoms relatifs du document.","aide":"Ils relient une proposition à un nom placé devant eux.","type":"zone","document":"phr","multiple":true},{"enonce":"Associe chaque pronom relatif à sa fonction dans la subordonnée.","aide":"Pose-toi la question : qui habite ? qu’est-ce que nous avons vu ?","type":"association","gauche":[{"id":"g0","texte":"qui (phrase 1)"},{"id":"g1","texte":"que (phrase 2)"},{"id":"g2","texte":"où (phrase 3)"}],"droite":[{"id":"d0","texte":"Complément circonstanciel de lieu"},{"id":"d1","texte":"Sujet de « habite »"},{"id":"d2","texte":"COD de « avons vu »"}]},{"enonce":"Quel est l’antécédent de « que » dans la phrase 2 ?","aide":"L’antécédent est le nom placé juste devant le pronom relatif.","type":"choix","options":[{"id":"a","texte":"trois heures"},{"id":"b","texte":"hier"},{"id":"c","texte":"nous"},{"id":"d","texte":"film"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m11","m22"]},"explication":"Les trois pronoms relatifs sont **qui**, **que** et **où** : chacun reprend un nom (cousine, film, salle)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**qui** est sujet de « habite », **que** est COD de « avons vu », **où** est complément circonstanciel de lieu."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’antécédent est **film** : c’est le film que nous avons vu."}]$ex$::jsonb),
  ('81b236ab-9380-5a11-9761-727d157acd9f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La virgule qui change tout","competence":"analyser-texte","situation":"Une seule virgule peut changer ce que dit une phrase. Trie des relatives, puis compare deux phrases presque identiques.","documents":[{"id":"rel","type":"texte","genre":"source","titre":"Quatre phrases","blocs":["Mon frère, qui habite à Nantes, vient dimanche.","Les romans qui finissent mal me touchent le plus.","Paris, où nous sommes nés, a beaucoup changé.","Je cherche le livre dont tu m’as parlé."],"source":"Phrases écrites pour l’exercice"},{"id":"duo","type":"texte","genre":"source","titre":"Deux versions","blocs":["A. Les touristes qui étaient fatigués sont rentrés.","B. Les touristes, qui étaient fatigués, sont rentrés."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Range chaque relative du document 1 : déterminative ou explicative ?","aide":"L’explicative est détachée par des virgules et peut être supprimée.","type":"categories","categories":[{"id":"c0","texte":"Déterminative"},{"id":"c1","texte":"Explicative"}],"items":[{"id":"i0","texte":"Mon frère, qui habite à Nantes, vient dimanche."},{"id":"i1","texte":"Je cherche le livre dont tu m’as parlé."},{"id":"i2","texte":"Les romans qui finissent mal me touchent le plus."},{"id":"i3","texte":"Paris, où nous sommes nés, a beaucoup changé."}]},{"enonce":"Associe chaque version du document 2 à son sens.","aide":"Sans virgule, la relative restreint : elle trie dans le groupe.","type":"association","gauche":[{"id":"g0","texte":"Version A (sans virgules)"},{"id":"g1","texte":"Version B (avec virgules)"}],"droite":[{"id":"d0","texte":"Tous les touristes étaient fatigués"},{"id":"d1","texte":"Seuls les touristes fatigués sont rentrés"}]},{"enonce":"Dans le document 1, touche le pronom relatif qui complète le verbe « parler de ».","aide":"Tu dis « parler DE ce livre » : le pronom remplace un complément introduit par « de ».","type":"zone","document":"rel","multiple":false},{"enonce":"Quelle relative du document 1 peut être supprimée sans perdre le sens de sa phrase ?","aide":"Cherche la relative détachée par des virgules.","type":"choix","options":[{"id":"a","texte":"Aucune des trois"},{"id":"b","texte":"dont tu m’as parlé"},{"id":"c","texte":"qui finissent mal"},{"id":"d","texte":"qui habite à Nantes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les relatives **entre virgules** sont explicatives ; celles qui restreignent le sens de l’antécédent, sans virgule, sont déterminatives."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"**Sans virgules**, la relative trie : seuls les fatigués rentrent. **Avec virgules**, elle ajoute une information valable pour tous."},{"cle":{"type":"zone","ids":["m29"]},"explication":"C’est **dont** : il remplace « de ce livre » et complète « as parlé »."},{"cle":{"type":"choix","ids":["d"]},"explication":"On peut supprimer **« qui habite à Nantes »** : c’est une explicative, elle ajoute une information."}]$ex$::jsonb),
  ('81b236ab-9380-5a11-9761-727d157acd9f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le notaire et sa place","competence":"analyser-texte","situation":"Une seule phrase de roman, cinq verbes, quatre pronoms relatifs : entraîne-toi à la démonter comme à l’oral, puis à dire ce qu’elle fait du personnage.","documents":[{"id":"notaire","type":"texte","genre":"recit","titre":"Une phrase en période","blocs":["Le vieux notaire, que tout le village saluait et dont personne ne connaissait le passé, habitait une maison qui donnait sur la place où se tenait le marché."],"source":"Phrase écrite pour l’exercice, à la manière d’un roman"}],"questions":[{"enonce":"Combien de verbes conjugués compte cette phrase ?","aide":"Les verbes sont : saluait, connaissait, habitait, donnait et un verbe pronominal.","type":"nombre"},{"enonce":"Associe chaque pronom relatif à sa fonction.","aide":"Reconstitue la phrase sans relatif : tout le village saluait le notaire…","type":"association","gauche":[{"id":"g0","texte":"que"},{"id":"g1","texte":"dont"},{"id":"g2","texte":"qui"},{"id":"g3","texte":"où"}],"droite":[{"id":"d0","texte":"Sujet de « donnait »"},{"id":"d1","texte":"Complément circonstanciel de lieu de « se tenait »"},{"id":"d2","texte":"COD de « saluait »"},{"id":"d3","texte":"Complément du nom « passé »"}]},{"enonce":"Touche l’antécédent du pronom « où ».","aide":"C’est le nom placé juste devant « où ».","type":"zone","document":"notaire","multiple":false},{"enonce":"Range les quatre relatives : déterminative ou explicative ?","aide":"Regarde la ponctuation autour de la relative.","type":"categories","categories":[{"id":"c0","texte":"Déterminative (sans virgule)"},{"id":"c1","texte":"Explicative (entre virgules)"}],"items":[{"id":"i0","texte":"où se tenait le marché"},{"id":"i1","texte":"que tout le village saluait"},{"id":"i2","texte":"qui donnait sur la place"},{"id":"i3","texte":"dont personne ne connaissait le passé"}]},{"enonce":"Que nous apprennent les relatives sur le notaire ?","aide":"Le personnage est décrit indirectement, par ce que les autres font de lui.","type":"choix","options":[{"id":"a","texte":"Il est très riche et généreux, ce que tout le village reconnaît"},{"id":"b","texte":"Il est en colère contre tout le village et refuse de lui parler"},{"id":"c","texte":"Il raconte lui-même son passé à qui veut l’entendre, sans détour"},{"id":"d","texte":"Il est connu par le regard des autres : on le salue, on ignore son passé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"Il y a **5** verbes conjugués (saluait, connaissait, habitait, donnait, se tenait) : donc cinq propositions."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**que** = COD de saluait ; **dont** = le passé du notaire (complément du nom) ; **qui** = sujet de donnait ; **où** = lieu."},{"cle":{"type":"zone","ids":["m22"]},"explication":"L’antécédent de « où » est **place**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Les deux relatives du notaire sont **entre virgules** (explicatives) ; celles de la maison et de la place sont **sans virgule** (déterminatives)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les relatives le **caractérisent indirectement** : salué de tous, mais au passé inconnu, il reste un homme mystérieux."}]$ex$::jsonb),
  ('23693833-c8df-578b-8a58-8d0b46307742'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"« Que » : relatif ou conjonction ?","competence":"manier-langue","situation":"Le petit mot « que » a plusieurs visages. Avant de le nommer à l’oral, teste s’il a un antécédent.","documents":[{"id":"q","type":"texte","genre":"source","titre":"Trois phrases avec « que »","blocs":["Le professeur annonce que l’oral commencera à huit heures.","Je souhaite que tu réussisses.","La copie que tu rends est très soignée."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les deux « que » qui sont des conjonctions de subordination.","aide":"Cherche un antécédent : s’il n’y en a pas, ce n’est pas un relatif.","type":"zone","document":"q","multiple":true},{"enonce":"Range chaque phrase selon la valeur de « que ».","aide":"Demande-toi : y a-t-il un nom devant « que » que le mot reprend ?","type":"categories","categories":[{"id":"c0","texte":"« que » conjonction (complétive)"},{"id":"c1","texte":"« que » pronom relatif"}],"items":[{"id":"i0","texte":"La photo que j’ai prise est floue."},{"id":"i1","texte":"Le livre que tu lis est beau."},{"id":"i2","texte":"Il faut que tu partes."},{"id":"i3","texte":"Je sais que tu mens."}]},{"enonce":"Dans la phrase 1, quelle est la fonction de la complétive « que l’oral commencera à huit heures » ?","aide":"Le professeur annonce quoi ? On peut remplacer la subordonnée par « quelque chose ».","type":"choix","options":[{"id":"a","texte":"Sujet de « annonce »"},{"id":"b","texte":"COD du verbe « annonce »"},{"id":"c","texte":"Complément du nom « professeur »"},{"id":"d","texte":"Attribut du sujet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m12"]},"explication":"Les **« que » des phrases 1 et 2** n’ont ni antécédent ni fonction ; celui de la phrase 3 reprend « copie » : c’est un relatif."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Avec un antécédent (livre, photo), « que » est **relatif** ; sans antécédent (je sais, il faut), c’est une **conjonction**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le professeur annonce **quelque chose** : la complétive est **COD** de « annonce »."}]$ex$::jsonb),
  ('23693833-c8df-578b-8a58-8d0b46307742'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une complétive, quatre métiers","competence":"manier-langue","situation":"Une complétive peut être sujet, attribut, COD ou complément d’un nom. Reconnais sa fonction, puis regarde le mode du verbe.","documents":[{"id":"fct","type":"texte","genre":"source","titre":"Quatre phrases","blocs":["Qu’il soit venu m’étonne.","Mon souhait est qu’il guérisse.","La crainte qu’il échoue la ronge.","Je veux qu’il vienne."],"source":"Phrases écrites pour l’exercice"},{"id":"duo","type":"texte","genre":"source","titre":"Deux phrases","blocs":["Je crois qu’il vient.","Je ne crois pas qu’il vienne."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Associe chaque phrase à la fonction de sa complétive.","aide":"Remplace la complétive par « quelque chose » et observe la place.","type":"association","gauche":[{"id":"g0","texte":"Phrase 1 : qu’il soit venu"},{"id":"g1","texte":"Phrase 2 : qu’il guérisse"},{"id":"g2","texte":"Phrase 3 : qu’il échoue"},{"id":"g3","texte":"Phrase 4 : qu’il vienne"}],"droite":[{"id":"d0","texte":"Attribut du sujet « souhait »"},{"id":"d1","texte":"Complément du nom « crainte »"},{"id":"d2","texte":"COD de « veux »"},{"id":"d3","texte":"Sujet de « étonne »"}]},{"enonce":"Dans la phrase 3, touche le nom que la complétive complète.","aide":"Le nom se trouve juste avant « qu’il échoue ».","type":"zone","document":"fct","multiple":false},{"enonce":"Range ces amorces selon le mode qui suit.","aide":"Déclaration, opinion, perception : indicatif. Volonté, sentiment, doute : subjonctif.","type":"categories","categories":[{"id":"c0","texte":"Indicatif"},{"id":"c1","texte":"Subjonctif"}],"items":[{"id":"i0","texte":"je doute que…"},{"id":"i1","texte":"il faut que…"},{"id":"i2","texte":"je sais que…"},{"id":"i3","texte":"je vois que…"},{"id":"i4","texte":"je veux que…"},{"id":"i5","texte":"je déclare que…"}]},{"enonce":"Dans le document 2, que révèle le passage de « vient » à « vienne » ?","aide":"La négation fait basculer la complétive au subjonctif.","type":"choix","options":[{"id":"a","texte":"Un changement de narrateur entre les deux phrases citées"},{"id":"b","texte":"Une simple variation de style, sans effet sur le sens"},{"id":"c","texte":"Un degré de certitude plus faible chez celui qui parle"},{"id":"d","texte":"Un changement de temps du récit, du présent au passé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Sujet (« quelque chose m’étonne »), attribut (après « est »), complément du nom (après « crainte »), COD (après « veux »)."},{"cle":{"type":"zone","ids":["m13"]},"explication":"La complétive complète le nom **crainte**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**Indicatif** après savoir, voir, déclarer ; **subjonctif** après vouloir, il faut, douter."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **subjonctif** après une négation dit le **doute** : celui qui parle n’est plus sûr."}]$ex$::jsonb),
  ('23693833-c8df-578b-8a58-8d0b46307742'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le capitaine dans la tempête","competence":"analyser-texte","situation":"Un court récit, quatre subordonnées qui commencent presque toutes par « que » ou « si ». À toi de les nommer comme l’examinateur l’attend.","documents":[{"id":"mer","type":"texte","genre":"recit","titre":"Le capitaine","blocs":["Le capitaine se demandait si l’orage passerait. Il savait que l’équipage avait peur. Il ne croyait pas qu’ils puissent tenir jusqu’à l’aube, mais il voulait qu’ils aient du courage."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui introduit la subordonnée interrogative indirecte.","aide":"Elle répond à la question « l’orage passera-t-il ? ».","type":"zone","document":"mer","multiple":false},{"enonce":"Pourquoi « puissent » est-il au subjonctif ?","aide":"Regarde le verbe de la principale : « ne croyait pas ».","type":"choix","options":[{"id":"a","texte":"La négation de « croyait » appelle le subjonctif : le capitaine doute"},{"id":"b","texte":"Parce que le récit est au passé et que le passé impose le subjonctif"},{"id":"c","texte":"Parce que la phrase est interrogative et appelle toujours le subjonctif"},{"id":"d","texte":"Parce que « tenir » est un verbe d’action qui veut le subjonctif"}],"multiple":false},{"enonce":"Associe chaque subordonnée à son analyse.","aide":"Nomme la subordonnée, donne sa fonction, puis le mode.","type":"association","gauche":[{"id":"g0","texte":"si l’orage passerait"},{"id":"g1","texte":"que l’équipage avait peur"},{"id":"g2","texte":"qu’ils puissent tenir jusqu’à l’aube"},{"id":"g3","texte":"qu’ils aient du courage"}],"droite":[{"id":"d0","texte":"Complétive COD de « savait », à l’indicatif"},{"id":"d1","texte":"Interrogative indirecte, COD de « se demandait »"},{"id":"d2","texte":"Complétive COD de « voulait », au subjonctif (volonté)"},{"id":"d3","texte":"Complétive COD de « croyait », au subjonctif (négation)"}]},{"enonce":"Laquelle est la meilleure formulation à l’oral pour « qu’ils aient du courage » ?","aide":"Pense à la formule complète : nature, fonction, mode.","type":"choix","options":[{"id":"a","texte":"Une relative, complément de « courage », au subjonctif car elle exprime un souhait"},{"id":"b","texte":"Une subordonnée avec « que », sans plus de précision sur sa nature ni son mode"},{"id":"c","texte":"Une circonstancielle de but, complément de « voulait », au subjonctif après « que »"},{"id":"d","texte":"Complétive conjonctive, COD de « voulait », au subjonctif car elle exprime une volonté"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"C’est **si** : « si l’orage passerait » est une interrogative indirecte."},{"cle":{"type":"choix","ids":["a"]},"explication":"La négation fait passer « croyait que » au **subjonctif** : le capitaine doute que l’équipage tienne."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Chaque subordonnée est **COD** ; seul le **mode** change avec le sens du verbe principal."},{"cle":{"type":"choix","ids":["d"]},"explication":"La bonne formule donne la **nature**, la **fonction** et la **raison du mode**."}]$ex$::jsonb),
  ('e30f66ef-4568-58bd-b96b-54ef8abd1d95'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quand, puisque, afin que","competence":"manier-langue","situation":"Trois phrases, trois circonstancielles. Repère les mots qui les introduisent, puis dis le rapport qu’elles expriment.","documents":[{"id":"circ","type":"texte","genre":"source","titre":"Trois phrases","blocs":["Quand la cloche sonne, les élèves sortent en rang.","Nous restons à la maison puisque la route est fermée.","Elle révise chaque soir afin que ses parents soient fiers."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les mots qui introduisent les subordonnées circonstancielles (la dernière locution compte deux mots).","aide":"Ce sont des conjonctions de subordination placées au début de chaque subordonnée.","type":"zone","document":"circ","multiple":true},{"enonce":"Associe chaque conjonction au rapport qu’elle exprime.","aide":"Pose les questions : quand ? pourquoi ? dans quel but ?","type":"association","gauche":[{"id":"g0","texte":"quand"},{"id":"g1","texte":"puisque"},{"id":"g2","texte":"afin que"}],"droite":[{"id":"d0","texte":"La cause"},{"id":"d1","texte":"Le but"},{"id":"d2","texte":"Le temps"}]},{"enonce":"Dans la phrase 3, pourquoi « soient » est-il au subjonctif ?","aide":"Pense à ce que signifie un but : on veut l’atteindre.","type":"choix","options":[{"id":"a","texte":"Par simple habitude de la langue, sans raison de sens"},{"id":"b","texte":"Parce que la phrase est au passé, donc au subjonctif"},{"id":"c","texte":"Parce que la phrase est négative, donc au subjonctif"},{"id":"d","texte":"Le but n’est pas encore réalisé au moment où l’on parle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m14","m23","m24"]},"explication":"Les subordonnants sont **quand**, **puisque** et la locution **afin que**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**quand** = temps, **puisque** = cause, **afin que** = but."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le but est **à venir**, non réalisé : il se dit au **subjonctif**."}]$ex$::jsonb),
  ('e30f66ef-4568-58bd-b96b-54ef8abd1d95'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Si j’avais su…","competence":"manier-langue","situation":"Le petit mot « si » dessine trois mondes : ce qui est possible, ce qui ne l’est pas, ce qui n’est plus possible. Puis repère une concession.","documents":[{"id":"hyp","type":"texte","genre":"source","titre":"Trois hypothèses","blocs":["Si je pars tôt, j’arriverai à l’heure.","Si je partais tôt, j’arriverais à l’heure.","Si j’étais parti tôt, je serais arrivé à l’heure."],"source":"Phrases écrites pour l’exercice"},{"id":"phr","type":"texte","genre":"source","titre":"Trois phrases de plaidoyer","blocs":["Bien que le chemin soit long, il marche jusqu’au soir.","Puisque tu insistes, je reste.","Si j’avais su, je serais venu plus tôt."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Associe chaque phrase du document 1 à sa valeur.","aide":"Regarde les temps : présent + futur, imparfait + conditionnel, plus-que-parfait + conditionnel passé.","type":"association","gauche":[{"id":"g0","texte":"Si je pars tôt, j’arriverai à l’heure."},{"id":"g1","texte":"Si je partais tôt, j’arriverais à l’heure."},{"id":"g2","texte":"Si j’étais parti tôt, je serais arrivé à l’heure."}],"droite":[{"id":"d0","texte":"Irréel du passé"},{"id":"d1","texte":"Irréel du présent"},{"id":"d2","texte":"Potentiel : la chose est possible"}]},{"enonce":"Complète la phrase à l’irréel du passé.","aide":"Plus-que-parfait dans la subordonnée, conditionnel passé dans la principale.","type":"trous","segments":["Si nous ",0," plus tôt, nous ",1," à l’heure."],"banque":["arriverons","serions arrivés","partirons","partions","arriverions","étions partis"]},{"enonce":"Dans le document 2, touche la locution de concession.","aide":"Elle exprime une opposition malgré laquelle l’action a lieu, et se construit avec le subjonctif.","type":"zone","document":"phr","multiple":true},{"enonce":"Que trahit « Si j’avais su, je serais venu plus tôt » ?","aide":"Une chose non réalisée dans le passé, qu’on ne peut plus changer.","type":"choix","options":[{"id":"a","texte":"Le regret"},{"id":"b","texte":"Une menace"},{"id":"c","texte":"Une habitude"},{"id":"d","texte":"Une promesse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Présent + futur : **potentiel** ; imparfait + conditionnel présent : **irréel du présent** ; plus-que-parfait + conditionnel passé : **irréel du passé**."},{"cle":{"type":"trous","trous":[["etions partis"],["serions arrives"]]},"affichage":"étions partis · serions arrivés","explication":"On écrit « Si nous **étions partis** plus tôt, nous **serions arrivés** à l’heure » : jamais de conditionnel après le « si » de condition."},{"cle":{"type":"zone","ids":["m0","m1"]},"explication":"La locution est **bien que** : le chemin est long, et pourtant il marche."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’irréel du passé dit le **regret** : on aurait voulu agir autrement."}]$ex$::jsonb),
  ('e30f66ef-4568-58bd-b96b-54ef8abd1d95'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’accusé prend la parole","competence":"argumenter","situation":"Un accusé se défend en deux phrases. À l’oral, il faudrait nommer chaque subordonnée, puis dire ce qu’elle fait du discours.","documents":[{"id":"plaid","type":"texte","genre":"source","titre":"Le plaidoyer","blocs":["Puisque vous m’accusez, je parlerai, bien que j’aie peur, pour que justice soit faite.","Si j’avais menti, je n’aurais pas osé venir ici."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Combien de verbes conjugués compte la première phrase ?","aide":"Compte : accusez, parlerai, aie, soit faite.","type":"nombre"},{"enonce":"Associe chaque subordonnée à son rapport.","aide":"Repère la conjonction : elle dit le rapport.","type":"association","gauche":[{"id":"g0","texte":"puisque vous m’accusez"},{"id":"g1","texte":"bien que j’aie peur"},{"id":"g2","texte":"pour que justice soit faite"},{"id":"g3","texte":"si j’avais menti"}],"droite":[{"id":"d0","texte":"Concession"},{"id":"d1","texte":"But"},{"id":"d2","texte":"Cause"},{"id":"d3","texte":"Condition (irréel du passé)"}]},{"enonce":"Que fait la concessive « bien que j’aie peur » dans le discours ?","aide":"C’est la seconde étape de l’analyse : interpréter.","type":"choix","options":[{"id":"a","texte":"Elle marque un retour en arrière vers les faits reprochés à l’accusé"},{"id":"b","texte":"Elle indique un changement de lieu, de la salle au lieu du crime"},{"id":"c","texte":"Elle accélère le récit en résumant les faits que l’accusé a vécus"},{"id":"d","texte":"Elle anticipe l’objection : il avoue sa peur avant qu’on la lui reproche"}],"multiple":false},{"enonce":"Complète.","aide":"Le système hypothétique se joue dans la principale.","type":"trous","segments":["Dans la phrase 2, le plus-que-parfait de la subordonnée appelle le conditionnel ",0," dans la principale."],"banque":["présent","futur","imparfait","passé"]},{"enonce":"Que dit l’ensemble de ces subordonnées de la manière dont parle l’accusé ?","aide":"Observe l’enchaînement des rapports logiques.","type":"choix","options":[{"id":"a","texte":"Il raconte longuement un souvenir d’enfance sans lien avec l’affaire"},{"id":"b","texte":"Il s’emporte et enchaîne ses arguments sans ordre ni méthode"},{"id":"c","texte":"Il se justifie avec méthode : cause, concession, but, hypothèse"},{"id":"d","texte":"Il refuse de répondre et se contente de nier sans argument"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Il y a **4** verbes conjugués : donc une principale et trois subordonnées."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**puisque** = cause ; **bien que** = concession ; **pour que** = but ; **si** = condition."},{"cle":{"type":"choix","ids":["d"]},"explication":"La concessive **anticipe l’objection** : c’est ce que rapporte la seconde étape (l’interprétation)."},{"cle":{"type":"trous","trous":[["passe"]]},"affichage":"passé","explication":"Plus-que-parfait + conditionnel **passé** : c’est l’irréel du passé."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les subordonnées forment un **raisonnement** : accusation, concession, but, hypothèse."}]$ex$::jsonb),
  ('64bb365c-d4df-5458-8f9b-f559ca493f9a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un quatrain à scander","competence":"analyser-texte","situation":"Voici un quatrain écrit pour l’exercice. Avant de l’interpréter, apprends à décrire sa forme : rimes, richesse, mesure.","documents":[{"id":"quat","type":"texte","genre":"poeme","titre":"Matin de plage","blocs":["Nous marchons vers la mer au lever du soleil,","Le sable est froid encor sous nos pieds fatigués,","Et les oiseaux chantaient, libres et rassurés.","Un ciel pâle s’étire et la mer s’émerveille."],"source":"Quatrain écrit pour l’exercice"}],"questions":[{"enonce":"Comment s’appellent les rimes de ce quatrain (soleil / fatigués / rassurés / s’émerveille) ?","aide":"Note les sons finals : A, B, B, A.","type":"choix","options":[{"id":"a","texte":"Rimes croisées (ABAB)"},{"id":"b","texte":"Rimes plates (AABB)"},{"id":"c","texte":"Rimes embrassées (ABBA)"},{"id":"d","texte":"Rimes suivies"}],"multiple":false},{"enonce":"Touche le mot qui rime avec « soleil » au vers 1.","aide":"Cherche dans le dernier vers un son final proche de « soleil ».","type":"zone","document":"quat","multiple":false},{"enonce":"Combien de syllabes compte le vers 1 (aucun e muet à compter) ?","aide":"Découpe : Nous / mar / chons / vers / la / mer…","type":"nombre"},{"enonce":"Associe chaque couple de mots à la richesse de sa rime.","aide":"Compte les sons identiques à la fin des deux mots.","type":"association","gauche":[{"id":"g0","texte":"vie / ici"},{"id":"g1","texte":"été / beauté"},{"id":"g2","texte":"cheval / rival"}],"droite":[{"id":"d0","texte":"Rime suffisante : deux sons communs"},{"id":"d1","texte":"Rime riche : trois sons communs ou plus"},{"id":"d2","texte":"Rime pauvre : un son commun"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Les rimes suivent le schéma A B B A : ce sont des **rimes embrassées**."},{"cle":{"type":"zone","ids":["m33","m34"]},"explication":"Le mot est **s’émerveille** : « soleil » et « émerveille » riment (les deux A)."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12","explication":"Nous-mar-chons-vers-la-mer | au-le-ver-du-so-leil : **12** syllabes, c’est un alexandrin avec césure après « mer »."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**vie / ici** [i] : pauvre ; **été / beauté** [te] : suffisante ; **cheval / rival** [val] : riche."}]$ex$::jsonb),
  ('64bb365c-d4df-5458-8f9b-f559ca493f9a'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les sens se répondent","competence":"analyser-texte","situation":"Quatre vers célèbres de Baudelaire. Repère ce qui se répond, nomme la figure, puis explique l’effet comme à l’oral.","documents":[{"id":"corr","type":"texte","genre":"poeme","titre":"Correspondances (extrait)","blocs":["Comme de longs échos qui de loin se confondent","Dans une ténébreuse et profonde unité,","Vaste comme la nuit et comme la clarté,","Les parfums, les couleurs et les sons se répondent."],"source":"Charles Baudelaire, Les Fleurs du mal, « Correspondances » (1857), vers 5 à 8"}],"questions":[{"enonce":"Touche les trois mots qui désignent des sensations de sens différents.","aide":"L’odorat, la vue, l’ouïe.","type":"zone","document":"corr","multiple":true},{"enonce":"Associe chaque procédé à son effet.","aide":"Nommer ne suffit pas : pense à l’effet produit.","type":"association","gauche":[{"id":"g0","texte":"Comparaison (« comme la nuit »)"},{"id":"g1","texte":"Synesthésie"},{"id":"g2","texte":"Rimes embrassées (ABBA)"}],"droite":[{"id":"d0","texte":"Fait se répondre des sensations de sens différents"},{"id":"d1","texte":"Rapproche deux réalités pour les éclairer"},{"id":"d2","texte":"Referment le quatrain sur lui-même"}]},{"enonce":"Quelle interprétation nomme la figure ET en tire un sens ?","aide":"À l’oral, une figure repérée doit être suivie d’un effet et d’une interprétation.","type":"choix","options":[{"id":"a","texte":"C’est une synesthésie, donc une figure de style qui mélange des sensations"},{"id":"b","texte":"La synesthésie unit le monde que le poète déchiffre : les sensations se répondent"},{"id":"c","texte":"Le vers est un alexandrin, donc une forme fixe très régulière à l’oreille"},{"id":"d","texte":"Baudelaire aime les parfums et les évoque pour le plaisir de les décrire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24","m26","m29"]},"explication":"Les trois sensations sont **parfums**, **couleurs** et **sons** : elles « se répondent »."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"La **comparaison** rapproche, la **synesthésie** mêle les sens, les **rimes embrassées** referment le quatrain."},{"cle":{"type":"choix","ids":["b"]},"explication":"La bonne réponse **nomme puis interprète** : le monde est une unité que le poète déchiffre."}]$ex$::jsonb),
  ('64bb365c-d4df-5458-8f9b-f559ca493f9a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux siècles de poèmes","competence":"se-reperer-temps","situation":"Trois œuvres du programme, quelques repères : place les œuvres dans le temps, rattache-les à leur parcours et à leur moment.","documents":[{"id":"frise","type":"frise","titre":"Quatre recueils","debut":1850,"fin":2050,"pas":50,"periodes":[],"evenements":[{"id":"z1","date":1870,"nom":"Cahiers de Douai"},{"id":"z2","date":1913,"nom":"Alcools"},{"id":"z3","date":1952,"nom":"La rage (Ponge)"},{"id":"z4","date":2021,"nom":"Mes forêts"}],"source":"Rimbaud (copie de 1870) ; Apollinaire (1913) ; Ponge (1952) ; Dorion (2021)"},{"id":"prog","type":"tableau","titre":"Trois œuvres au programme","colonnes":["Auteur","Œuvre"],"lignes":[["Arthur Rimbaud","Les Cahiers de Douai"],["Francis Ponge","La rage de l’expression"],["Hélène Dorion","Mes forêts"]],"enteteLignes":true}],"questions":[{"enonce":"Sur la frise, touche l’œuvre qui est la première d’une autrice vivante inscrite au programme.","aide":"C’est la plus récente des quatre.","type":"zone","document":"frise","multiple":false},{"enonce":"Remets ces moments de la poésie dans l’ordre chronologique.","aide":"Du XIXe siècle jusqu’au XXIe.","type":"ordre","items":[{"id":"a","texte":"Le romantisme (Hugo, Lamartine)"},{"id":"b","texte":"La traversée intime du monde naturel de Dorion"},{"id":"c","texte":"Le poème-atelier de Ponge"},{"id":"d","texte":"Le symbolisme et la modernité (Baudelaire, Rimbaud, Mallarmé)"}]},{"enonce":"Associe chaque œuvre du document 2 à son parcours.","aide":"Chaque parcours résume le fil de lecture de l’œuvre.","type":"association","gauche":[{"id":"g0","texte":"Les Cahiers de Douai"},{"id":"g1","texte":"La rage de l’expression"},{"id":"g2","texte":"Mes forêts"}],"droite":[{"id":"d0","texte":"La poésie, la nature, l’intime"},{"id":"d1","texte":"Émancipations créatrices"},{"id":"d2","texte":"Dans l’atelier du poète"}]},{"enonce":"Laquelle de ces phrases d’oral nomme un procédé ET l’interprète ?","aide":"Cherche la phrase qui donne un effet, pas seulement un nom.","type":"choix","options":[{"id":"a","texte":"« Il y a une allitération en [s] qui revient plusieurs fois dans les deux strophes. »"},{"id":"b","texte":"« C’est une figure de style très utilisée en poésie, ce qui donne du rythme. »"},{"id":"c","texte":"« Le poète a écrit ce texte très jeune, et cela se voit à son style. »"},{"id":"d","texte":"« L’allitération en [s] fait entendre le vent : le poème devient sensation. »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"C’est **Mes forêts** (2021), d’Hélène Dorion."},{"cle":{"type":"ordre","ids":["a","d","c","b"]},"explication":"Ordre : **romantisme, symbolisme et modernité, Ponge, Dorion**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Cahiers de Douai** : émancipations créatrices ; **La rage de l’expression** : dans l’atelier du poète ; **Mes forêts** : la poésie, la nature, l’intime."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il faut **nommer puis interpréter** : seule la première phrase le fait."}]$ex$::jsonb),
  ('41813cdd-0691-5f2e-a3ec-b78150d1191c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Sensation, le poème de la fugue","competence":"analyser-texte","situation":"Le poème le plus célèbre de la veine « fugue » : un adolescent rêve de marcher dans la nature. Relis, repère, range.","documents":[{"id":"sens","type":"texte","genre":"poeme","titre":"Sensation","blocs":["Par les soirs bleus d’été, j’irai dans les sentiers,","Picoté par les blés, fouler l’herbe menue :","Rêveur, j’en sentirai la fraîcheur à mes pieds.","Je laisserai le vent baigner ma tête nue.","","Je ne parlerai pas, je ne penserai rien :","Mais l’amour infini me montera dans l’âme,","Et j’irai loin, bien loin, comme un bohémien,","Par la Nature, — heureux comme avec une femme."],"source":"Arthur Rimbaud, « Sensation » (1870), Cahiers de Douai"}],"questions":[{"enonce":"Touche le mot qui compare le poète à un vagabond.","aide":"Il est au vers 7, après « comme un ».","type":"zone","document":"sens","multiple":false},{"enonce":"Associe chaque strophe à ce qu’elle met en scène.","aide":"Regarde ce qui domine : les gestes du corps, puis l’élan vers l’infini.","type":"association","gauche":[{"id":"g0","texte":"Strophe 1"},{"id":"g1","texte":"Strophe 2"}],"droite":[{"id":"d0","texte":"Le silence, l’amour infini et la fuite loin avec la Nature"},{"id":"d1","texte":"Le corps qui marche et sent : sentiers, blés, fraîcheur, vent"}]},{"enonce":"Quel temps domine dans le poème, et que dit-il ?","aide":"Relève « j’irai », « je sentirai », « je laisserai ».","type":"choix","options":[{"id":"a","texte":"Le futur : le poète rêve une fugue qu’il n’a pas encore faite"},{"id":"b","texte":"L’imparfait : il décrit une habitude de promenade du poète"},{"id":"c","texte":"Le passé simple : il raconte une fugue qu’il a déjà faite"},{"id":"d","texte":"Le présent : il décrit ce qu’il voit en train de marcher"}],"multiple":false},{"enonce":"Range ces poèmes selon la veine du recueil.","aide":"Trois veines : la nature qui remplace la maison, le pouvoir attaqué, la beauté retournée.","type":"categories","categories":[{"id":"c0","texte":"Fugue et sensation"},{"id":"c1","texte":"Satire politique et sociale"},{"id":"c2","texte":"Provocation et corps"}],"items":[{"id":"i0","texte":"Les Reparties de Nina"},{"id":"i1","texte":"Sensation"},{"id":"i2","texte":"Le Forgeron"},{"id":"i3","texte":"Rages de Césars"},{"id":"i4","texte":"Vénus Anadyomène"},{"id":"i5","texte":"Ma Bohème"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m61"]},"explication":"Le mot est **bohémien** : le poète se rêve en vagabond."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"La **strophe 1** dit les sensations du corps ; la **strophe 2** le silence, l’amour infini et la fuite."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **futur** projette un rêve : la fugue est promesse, pas encore vécue."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c1","i4":"c2","i5":"c0"}},"explication":"**Sensation** et **Ma Bohème** : fugue ; **Rages de Césars** et **Le Forgeron** : satire ; **Vénus Anadyomène** et **Les Reparties de Nina** : provocation."}]$ex$::jsonb),
  ('41813cdd-0691-5f2e-a3ec-b78150d1191c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La chute du Dormeur du val","competence":"analyser-texte","situation":"Treize vers de nature riante, puis la chute. Observe le dernier tercet : comment Rimbaud retarde la révélation.","documents":[{"id":"dorm","type":"texte","genre":"poeme","titre":"Le Dormeur du val (dernier tercet)","blocs":["Les parfums ne font pas frissonner sa narine ;","Il dort dans le soleil, la main sur sa poitrine,","Tranquille. Il a deux trous rouges au côté droit."],"source":"Arthur Rimbaud, « Le Dormeur du val » (1870), Cahiers de Douai"}],"questions":[{"enonce":"Touche le mot rejeté au début du dernier vers, juste avant la chute.","aide":"C’est un adjectif isolé par un point.","type":"zone","document":"dorm","multiple":false},{"enonce":"Quel effet produit ce rejet ?","aide":"Le mot dit la paix, mais il est suivi d’un point.","type":"choix","options":[{"id":"a","texte":"Il installe un calme trompeur qui prépare la chute"},{"id":"b","texte":"Il exprime la colère violente du poète contre la guerre"},{"id":"c","texte":"Il accélère le rythme du vers pour traduire l’action"},{"id":"d","texte":"Il marque une négation qui contredit le vers précédent"}],"multiple":false},{"enonce":"Touche les trois mots qui révèlent que le soldat est mort.","aide":"Un chiffre, un nom et un adjectif de couleur.","type":"zone","document":"dorm","multiple":true},{"enonce":"Remets les mouvements du poème dans l’ordre.","aide":"Du décor vers le personnage, puis la révélation.","type":"ordre","items":[{"id":"a","texte":"Un val lumineux où chante une rivière"},{"id":"b","texte":"La chute : les deux trous rouges au côté droit"},{"id":"c","texte":"Un jeune soldat étendu dans l’herbe"},{"id":"d","texte":"Le soldat dort : la Nature est priée de le bercer"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"C’est **Tranquille** : ce rejet isole un mot calme juste avant la révélation."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le rejet **suspend** la phrase : le calme apparent rend la chute plus violente."},{"cle":{"type":"zone","ids":["m21","m22","m23"]},"explication":"Ce sont **deux trous rouges** : les blessures que le soldat porte au côté droit."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"Le poème va du **décor** au **soldat**, puis à l’**appel à la Nature**, enfin à la **chute**."}]$ex$::jsonb),
