   $ex${"titre":"Une triple émancipation","competence":"argumenter","situation":"Sujet de dissertation : comment le parcours « émancipations créatrices » se construit-il ? Range les exemples, complète le plan, trouve le fil.","documents":[{"id":"sujet","type":"texte","genre":"consigne","titre":"Sujet de dissertation","blocs":["Dans les Cahiers de Douai, le poème est-il pour Rimbaud un lieu de liberté ?"],"source":"Sujet écrit pour l’exercice"},{"id":"plan","type":"tableau","titre":"Le plan : contre quoi, de qui","colonnes":["Contre quoi","De qui"],"lignes":[["La famille et la province","L’adolescent"],["L’ordre impérial et clérical","Le citoyen"],["Les formes héritées","Le poète"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque exemple dans la bonne partie du plan.","aide":"Famille et province / ordre impérial et clérical / formes héritées.","type":"categories","categories":[{"id":"c0","texte":"L’adolescent"},{"id":"c1","texte":"Le citoyen"},{"id":"c2","texte":"Le poète"}],"items":[{"id":"i0","texte":"La critique de l’Église et de l’armée"},{"id":"i1","texte":"Les enjambements violents dans un sonnet régulier"},{"id":"i2","texte":"La satire des Césars et du pouvoir"},{"id":"i3","texte":"La fugue à pied loin de Charleville"},{"id":"i4","texte":"Le mot familier glissé dans un moule noble"},{"id":"i5","texte":"La nature qui remplace la maison"}]},{"enonce":"Complète le plan.","aide":"Reprends le tableau du document 2.","type":"trous","segments":["I. L’",0," qui fuit sa famille ; II. Le ",1," qui s’en prend à l’ordre impérial ; III. Le ",2," qui bouscule les formes héritées."],"banque":["adolescent","professeur","poète","soldat","citoyen"]},{"enonce":"Quel fil relie ces trois émancipations ?","aide":"Pense à la marche, au corps, à la nature dans les poèmes de fugue.","type":"choix","options":[{"id":"a","texte":"La nostalgie de l’enfance, que le poète regrette dans chaque poème"},{"id":"b","texte":"Le retour à la tradition classique, que le poète retrouve peu à peu"},{"id":"c","texte":"Le refus de toute forme de poésie, jugée inutile par le poète"},{"id":"d","texte":"La sensation : le monde est d’abord senti avant d’être pensé"}],"multiple":false},{"enonce":"Pourquoi ne faut-il pas chercher une progression narrative dans le recueil ?","aide":"Pense à l’origine du recueil.","type":"choix","options":[{"id":"a","texte":"Rimbaud n’a pas composé ce recueil : ce sont des poèmes recopiés à Douai"},{"id":"b","texte":"Parce qu’ils ont tous été publiés et écrits après la mort du poète"},{"id":"c","texte":"Parce qu’ils n’ont aucun thème commun ni aucune unité d’inspiration"},{"id":"d","texte":"Parce que les poèmes sont tous écrits en prose et non en vers"}],"multiple":false}]}$ex$::jsonb,
