   $ex${"titre":"Une page du carnet de l’atelier","competence":"analyser-texte","situation":"Voici une page imaginée à la manière d’un carnet d’atelier. Repère ce qui la rend « pongienne », sans jamais chercher le miroir des sentiments.","documents":[{"id":"brouillon","type":"texte","genre":"recit","titre":"Mardi 3 mars","blocs":["Le galet. Première définition : le galet est un œuf de pierre. Non : trop joli, trop humain. Je barre. Seconde définition : le galet est ce que la mer a fini de dire. Non plus : c’est moi qui parle, pas le galet. Je reprends demain, le dictionnaire ouvert."],"source":"Brouillon écrit pour l’exercice, à la manière d’un carnet d’atelier"}],"questions":[{"enonce":"Touche les deux verbes qui disent que l’auteur corrige et recommence.","aide":"Il rature, puis il revient au travail le lendemain.","type":"zone","document":"brouillon","multiple":true},{"enonce":"Range chaque trait : atelier de Ponge ou lyrisme romantique ?","aide":"Atelier : dates, ratures, dictionnaire. Lyrisme : les sentiments du « je ».","type":"categories","categories":[{"id":"c0","texte":"Écriture d’atelier"},{"id":"c1","texte":"Lyrisme romantique"}],"items":[{"id":"i0","texte":"Le galet est le miroir de ma tristesse"},{"id":"i1","texte":"Une séance datée"},{"id":"i2","texte":"Le dictionnaire ouvert"},{"id":"i3","texte":"Je dis mon chagrin à la mer"},{"id":"i4","texte":"Une définition rayée"}]},{"enonce":"Pourquoi l’auteur rejette-t-il « un œuf de pierre » ?","aide":"Relis : « trop joli, trop humain ».","type":"choix","options":[{"id":"a","texte":"Parce qu’elle est trop compliquée pour un lecteur pressé de comprendre"},{"id":"b","texte":"Parce qu’elle est trop scientifique et trop éloignée du langage courant"},{"id":"c","texte":"L’image est trop jolie et trop humaine : elle n’est pas fidèle à l’objet"},{"id":"d","texte":"Parce qu’elle est recopiée telle quelle dans un dictionnaire de la langue"}],"multiple":false},{"enonce":"Complète.","aide":"Pense au mot « atelier ».","type":"trous","segments":["Pour Ponge, le poème n’est plus un ",0," mais un ",1,"."],"banque":["message","chant","processus","résultat"]}]}$ex$::jsonb,
