   $ex${"titre":"Les quatre étapes du réflexe","competence":"manier-langue","situation":"À l’oral, la question de grammaire se gagne avec une méthode. Remets les étapes dans l’ordre, puis applique-les à une phrase.","documents":[{"id":"etapes","type":"fiche","modele":"affiche","entete":"La méthode, en désordre","sousTitre":"Question de grammaire","emoji":"🎤","teinte":"violet","lignes":[{"texte":"Nommer : nature et fonction"},{"texte":"Interpréter l’effet dans le texte"},{"texte":"Relire la phrase en entier à voix haute"},{"texte":"Identifier : compter les verbes conjugués"}],"pied":"Fiche écrite pour l’exercice"},{"id":"phr","type":"texte","genre":"source","titre":"La phrase de l’examinateur","blocs":["Quand la nuit tombe, le vieux berger rentre ses moutons qui ont faim."],"source":"Phrase écrite pour l’exercice"}],"questions":[{"enonce":"Remets les quatre étapes de la méthode dans l’ordre.","aide":"On relit avant de compter, on nomme avant d’interpréter.","type":"ordre","items":[{"id":"a","texte":"Identifier : compter les verbes conjugués"},{"id":"b","texte":"Nommer : nature et fonction"},{"id":"c","texte":"Interpréter l’effet dans le texte"},{"id":"d","texte":"Relire la phrase en entier à voix haute"}]},{"enonce":"Combien de verbes conjugués compte la phrase du document 2 ?","aide":"Cherche tombe, rentre, ont.","type":"nombre"},{"enonce":"Touche le pronom relatif de la phrase.","aide":"Il reprend « moutons ».","type":"zone","document":"phr","multiple":false},{"enonce":"Quelle est la fonction de « qui » ?","aide":"Qui a faim ? Les moutons.","type":"choix","options":[{"id":"a","texte":"Complément du nom « berger »"},{"id":"b","texte":"Sujet de « ont »"},{"id":"c","texte":"Attribut de « moutons »"},{"id":"d","texte":"COD de « rentre »"}],"multiple":false}]}$ex$::jsonb,
