"},{"id":"d1","texte":"Nature puis fonction"},{"id":"d2","texte":"Totale ou partielle, et sa portée"}]},{"enonce":"Quelle interprétation de « n’avait jamais avoué » est juste ?","aide":"Que dit « jamais » sur le temps ?","type":"choix","options":[{"id":"a","texte":"Elle insiste sur la durée du silence"},{"id":"b","texte":"Elle annonce un futur proche"},{"id":"c","texte":"Elle exprime une restriction"},{"id":"d","texte":"Elle marque une explosion de colère"}],"multiple":false}]}$ex$::jsonb,
