   $ex${"titre":"La question de grammaire en entier","competence":"argumenter","situation":"Une phrase de plaidoyer, une analyse complète : découpe, nomme, puis interprète comme à l’oral.","documents":[{"id":"plaid","type":"texte","genre":"source","titre":"La phrase de l’examinateur","blocs":["Quoique vous me jugiez coupable, je ne crois pas que la vérité soit de votre côté, parce que vous n’avez rien écouté."],"source":"Phrase écrite pour l’exercice"}],"questions":[{"enonce":"Combien de propositions compte cette phrase ?","aide":"Compte : jugiez, crois, soit, avez écouté.","type":"nombre"},{"enonce":"Associe chaque proposition à son analyse.","aide":"Chaque subordonnée se nomme puis se situe.","type":"association","gauche":[{"id":"g0","texte":"Quoique vous me jugiez coupable"},{"id":"g1","texte":"je ne crois pas"},{"id":"g2","texte":"que la vérité soit de votre côté"},{"id":"g3","texte":"parce que vous n’avez rien écouté"}],"droite":[{"id":"d0","texte":"Complétive COD de « crois », au subjonctif après une négation"},{"id":"d1","texte":"Circonstancielle de concession, au subjonctif"},{"id":"d2","texte":"Circonstancielle de cause, à l’indicatif"},{"id":"d3","texte":"Proposition principale"}]},{"enonce":"Analysez la négation de « vous n’avez rien écouté ».","aide":"Regarde le second mot de la négation.","type":"choix","options":[{"id":"a","texte":"Négation totale (ne… pas), qui porte sur l’ensemble de la phrase"},{"id":"b","texte":"Pas de négation : la phrase est à la forme affirmative du verbe"},{"id":"c","texte":"Restriction (ne… que), qui limite le sens du complément du verbe"},{"id":"d","texte":"Négation partielle (ne… rien), qui porte sur le COD du verbe"}],"multiple":false},{"enonce":"Complète la formule d’oral.","aide":"Nature puis fonction.","type":"trous","segments":["« Que la vérité soit de votre côté » est une subordonnée conjonctive ",0,", ",1," du verbe « crois »."],"banque":["sujet","complétive","relative","attribut","COD"]},{"enonce":"Que produit le subjonctif après « je ne crois pas » ?","aide":"Le mode dit le degré de certitude.","type":"choix","options":[{"id":"a","texte":"Il marque un ordre que le locuteur adresse à quelqu’un"},{"id":"b","texte":"Il accélère le récit en passant à un temps bref"},{"id":"c","texte":"Il révèle le doute et l’incertitude du locuteur"},{"id":"d","texte":"Il marque la certitude totale du locuteur sur le fait"}],"multiple":false}]}$ex$::jsonb,
