   $ex${"titre":"Qui raconte, et quand ?","competence":"analyser-texte","situation":"Trois questions à poser à tout récit : qui raconte, depuis quel point de vue, à quel moment ? Applique-les à un court extrait.","documents":[{"id":"soir","type":"texte","genre":"recit","titre":"Ce soir-là","blocs":["Ce soir-là, j’ai vu Léa pousser la porte du café. Elle cherchait quelqu’un ; je ne savais pas qui. Bien plus tard, dans mon jardin, j’ai compris que c’était moi."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Qui raconte ?","aide":"Regarde « j’ai vu », « je ne savais pas ».","type":"choix","options":[{"id":"a","texte":"Un narrateur absent, le récit se racontant tout seul"},{"id":"b","texte":"Un narrateur externe, qui n’est pas un personnage"},{"id":"c","texte":"Un narrateur omniscient, qui sait tout des personnages"},{"id":"d","texte":"Un narrateur interne : un personnage qui dit « je »"}],"multiple":false},{"enonce":"Touche les trois mots qui montrent que le récit est fait après coup.","aide":"Ils marquent un intervalle de temps.","type":"zone","document":"soir","multiple":true},{"enonce":"Que montre « je ne savais pas qui » ?","aide":"Il ne connaît pas les pensées de Léa.","type":"choix","options":[{"id":"a","texte":"Le narrateur sait tout de Léa et le dit au lecteur : focalisation zéro"},{"id":"b","texte":"Le récit se limite à ce que le narrateur sait : focalisation interne"},{"id":"c","texte":"Le narrateur observe Léa de l’extérieur : focalisation externe"},{"id":"d","texte":"Le récit est enchâssé : un second narrateur raconte à l’intérieur"}],"multiple":false}]}$ex$::jsonb,
