   $ex${"titre":"La coupe de l’immeuble","competence":"observer-schema","situation":"Zola montre l’immeuble comme une coupe : on voit tous les étages à la fois. Observe ce que l’on montre et ce que l’on cache.","documents":[{"id":"coupe","type":"fiche","modele":"panneau","entete":"Coupe de l’immeuble","sousTitre":"Rue de Choiseul","emoji":"🏛️","teinte":"ambre","lignes":[{"texte":"Sous les toits : les chambres des bonnes","id":"z1"},{"texte":"Aux étages : salons et réceptions","id":"z2"},{"texte":"Le grand escalier : faux marbre, tapis, chauffage, silence","id":"z3"},{"texte":"L’escalier de service et la cour intérieure","id":"z4"}],"pied":"Du haut vers le bas"}],"questions":[{"enonce":"Touche le décor que la maison offre aux visiteurs pour paraître honnête.","aide":"C’est ce que l’on montre.","type":"zone","document":"coupe","multiple":false},{"enonce":"Touche l’endroit d’où les bonnes crient les secrets des maîtres d’une fenêtre à l’autre.","aide":"Un espace que les visiteurs ne voient pas.","type":"zone","document":"coupe","multiple":false},{"enonce":"Associe ce que l’on montre à ce que l’on cache.","aide":"À chaque décor répond son envers.","type":"association","gauche":[{"id":"g0","texte":"Le grand escalier"},{"id":"g1","texte":"Les salons et leurs réceptions"},{"id":"g2","texte":"La façade d’une maison honnête"}],"droite":[{"id":"d0","texte":"La vie réelle des locataires"},{"id":"d1","texte":"L’escalier de service et la cour"},{"id":"d2","texte":"Les chambres, les dettes, les maîtresses"}]},{"enonce":"Pourquoi Zola montre-t-il l’immeuble comme une coupe ?","aide":"Le cours dit que le décor n’est là que pour cacher.","type":"choix","options":[{"id":"a","texte":"Pour rendre le roman plus court en résumant la vie de chaque étage"},{"id":"b","texte":"Pour décrire en détail l’architecture de l’immeuble haussmannien"},{"id":"c","texte":"Pour imiter le plan précis qu’un architecte dessinerait du bâtiment"},{"id":"d","texte":"Pour voir tous les étages à la fois : le décor est là pour cacher"}],"multiple":false}]}$ex$::jsonb,
