   $ex${"titre":"L’escalier de Mme Lenoir","competence":"analyser-texte","situation":"Un passage écrit pour l’exercice, à la manière de Zola, décrit un escalier et les pensées d’une locataire. Repère les procédés.","documents":[{"id":"esc","type":"texte","genre":"recit","titre":"L’escalier","blocs":["L’escalier montait, large, de faux marbre jusqu’au troisième, tapissé de rouge, chauffé comme un salon ; et l’on y gardait ce silence qui dit les maisons honnêtes. Madame Lenoir le gravissait, satisfaite. Quelle maison respectable, décidément, et comme on y était tranquille ! Personne, bien sûr, ne saurait rien de ce qui se passait là-haut, sous les toits, et qui irait s’en inquiéter ?"],"source":"Texte écrit pour l’exercice, à la manière de Zola"}],"questions":[{"enonce":"Touche le mot qui trahit le décor : derrière la noblesse du marbre, tout est factice.","aide":"Un adjectif qui dit le contraire de « vrai ».","type":"zone","document":"esc","multiple":false},{"enonce":"Range chaque phrase : narration ou pensée du personnage (discours indirect libre) ?","aide":"Une exclamation sans « pensa-t-elle » est la pensée du personnage.","type":"categories","categories":[{"id":"c0","texte":"Narration"},{"id":"c1","texte":"Pensée (discours indirect libre)"}],"items":[{"id":"i0","texte":"L’escalier montait jusqu’au troisième, tapissé de rouge."},{"id":"i1","texte":"Personne, bien sûr, ne saurait rien, et qui irait s’en inquiéter ?"},{"id":"i2","texte":"Quelle maison respectable, décidément, et comme on y était tranquille !"},{"id":"i3","texte":"Madame Lenoir le gravissait, satisfaite."}]},{"enonce":"Quel est l’effet de l’ironie dans ce passage ?","aide":"Regarde « sous les toits » et « qui irait s’en inquiéter ? ».","type":"choix","options":[{"id":"a","texte":"Le lecteur voit ce que le personnage refuse de voir : la vie cachée"},{"id":"b","texte":"Elle annonce un crime qui sera commis par un locataire de la maison"},{"id":"c","texte":"Elle fait admirer la maison bourgeoise et la vertu de ses habitants"},{"id":"d","texte":"Elle rend le texte plus poétique en embellissant la vie de la maison"}],"multiple":false},{"enonce":"Associe chaque procédé naturaliste à son effet.","aide":"Relis le tableau « Le regard naturaliste » du cours.","type":"association","gauche":[{"id":"g0","texte":"Focalisation par un nouveau venu"},{"id":"g1","texte":"Discours indirect libre"},{"id":"g2","texte":"Ironie"},{"id":"g3","texte":"Satire"}],"droite":[{"id":"d0","texte":"On entend les pensées sans commentaire"},{"id":"d1","texte":"Le lecteur découvre l’immeuble comme Octave"},{"id":"d2","texte":"Elle vire parfois à la farce"},{"id":"d3","texte":"Contraste entre grands mots et actes"}]}]}$ex$::jsonb,
