   $ex${"titre":"Une voix qui parle depuis son jardin","competence":"analyser-texte","situation":"Un texte écrit pour l’exercice imite la voix d’une vieille narratrice. Repère ce qui fait de ce récit une parole.","documents":[{"id":"voix","type":"texte","genre":"recit","titre":"Un soir de jardin","blocs":["Je suis vieille à présent, et je vous parle depuis mon jardin. Ma grand-mère disait, le soir, que la pluie mouille la tête sans jamais entrer dans le cœur de celle qui se tient droite. Elle avait des contes pour chaque nuit, et je les sais encore, comme on sait le chemin de sa case."],"source":"Texte écrit pour l’exercice, dans l’esprit du roman — ce n’est pas un extrait"}],"questions":[{"enonce":"Touche le mot qui montre que la narratrice raconte au soir de sa vie.","aide":"Un adjectif d’âge.","type":"zone","document":"voix","multiple":false},{"enonce":"Touche le mot qui désigne le genre oral transmis chaque nuit.","aide":"Ce ne sont pas des proverbes.","type":"zone","document":"voix","multiple":false},{"enonce":"Que signifie l’image de la pluie et du cœur dans ce texte ?","aide":"Relie « se tient droite » à l’idée de dignité.","type":"choix","options":[{"id":"a","texte":"Il faut se protéger de la pluie avec un parapluie, sinon on tombe malade"},{"id":"b","texte":"La pluie annonce toujours un malheur qui va s’abattre sur le jardin"},{"id":"c","texte":"Les épreuves glissent sur celle qui reste debout : la dignité protège"},{"id":"d","texte":"Le cœur de la narratrice est malade et la pluie aggrave son mal"}],"multiple":false},{"enonce":"Associe chaque procédé à son effet.","aide":"Relis le tableau « Une écriture de la voix ».","type":"association","gauche":[{"id":"g0","texte":"Première personne rétrospective"},{"id":"g1","texte":"Proverbes et images créoles"},{"id":"g2","texte":"Merveilleux"},{"id":"g3","texte":"Phrases amples et rythmées"}],"droite":[{"id":"d0","texte":"Le roman se lit comme un chant"},{"id":"d1","texte":"La sagesse de l’âge éclaire l’enfance"},{"id":"d2","texte":"Il appartient au monde des personnages, sans être expliqué"},{"id":"d3","texte":"Le récit garde la saveur de la parole"}]}]}$ex$::jsonb,
