   $ex${"titre":"Le soldat de la promenade","competence":"analyser-texte","situation":"Une scène écrite pour l’exercice s’inspire de l’esprit du Menteur. Repère l’exagération et les ressorts comiques.","documents":[{"id":"promenade","type":"texte","genre":"theatre","titre":"Le soldat de la promenade","auteur":"Scène écrite pour l’exercice, dans l’esprit du Menteur (Corneille, 1644)","blocs":[{"didascalie":"Une promenade au bord de l’eau. Damis aborde deux jeunes femmes ; son valet Paulin le suit."},{"personnage":"Damis","replique":"Je reviens de dix campagnes, mesdames, de vingt sièges et de mille combats, sans une égratignure !"},{"personnage":"Paulin","replique":"(À part.) Le plus loin qu’il ait été, c’est la foire du village."},{"personnage":"Hortense","replique":"Dix campagnes ? Vous n’avez pas trente ans."},{"personnage":"Damis","replique":"C’est que je suis né soldat : j’ai commencé au berceau."}],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui pousse l’exagération le plus loin dans la première tirade.","aide":"Le plus grand des trois nombres.","type":"zone","document":"promenade","multiple":false},{"enonce":"Range chaque élément selon le type de comique.","aide":"Les mots exagèrent ; la situation oppose ce qu’on sait ; le menteur enchaîne.","type":"categories","categories":[{"id":"c0","texte":"Comique de mots"},{"id":"c1","texte":"Comique de situation"},{"id":"c2","texte":"Comique de répétition"}],"items":[{"id":"i0","texte":"Damis invente « né soldat » pour rattraper ses chiffres"},{"id":"i1","texte":"Paulin sait la vérité, Hortense l’ignore"},{"id":"i2","texte":"Les chiffres gonflés : dix campagnes, vingt sièges, mille combats"}]},{"enonce":"Quel rôle joue l’aparté de Paulin ?","aide":"Il parle « à part » : à qui ?","type":"choix","options":[{"id":"a","texte":"Il avertit Hortense du danger qui la guette dans la scène"},{"id":"b","texte":"Il interrompt l’action et arrête la pièce pendant quelques minutes"},{"id":"c","texte":"Il fait du spectateur son complice, à qui il confie la vérité"},{"id":"d","texte":"Il menace Damis de tout révéler à Hortense devant les autres"}],"multiple":false},{"enonce":"Pourquoi le spectateur rit-il de Damis sans le condamner ?","aide":"Le cours parle d’un menteur jamais pris de court.","type":"choix","options":[{"id":"a","texte":"Parce qu’il admire autant qu’il rit : ses mensonges sont des numéros d’artiste"},{"id":"b","texte":"Parce que la scène est tragique et que le rire vient du soulagement"},{"id":"c","texte":"Parce que Damis est puni à la fin de la pièce, ce qui rassure le public"},{"id":"d","texte":"Parce que personne n’est dupe de ses mensonges, donc rien n’est grave"}],"multiple":false}]}$ex$::jsonb,
