ssion de la comédie.","type":"choix","options":[{"id":"a","texte":"Parce que la pièce est en prose, alors que la comédie classique est en vers"},{"id":"b","texte":"Parce que Dorante meurt à la fin, ce qui surprend dans une comédie"},{"id":"c","texte":"Parce que Corneille change de genre en cours de pièce et passe au drame"},{"id":"d","texte":"Parce qu’une comédie doit corriger les mœurs, ce que celle-ci ne fait pas"}],"multiple":false}]}$ex$::jsonb,
